insert into private.questions (id,assessment_id,skill,kind,variants) values ('numerique:nu-c','final-numerique','Shannon','numeric','[{"prompt":"<p>Canal de 1 MHz, SNR de 15 (linéaire). Calculez la capacité, en Mbit/s.</p>","unit":"Mbit/s","answer":{"value":4,"rel":0.02},"display":"4 Mbit/s","explanation":"<p>C = B log₂(1 + S/N).</p>"},{"prompt":"<p>Canal de 2 MHz, SNR de 31 (linéaire). Calculez la capacité, en Mbit/s.</p>","unit":"Mbit/s","answer":{"value":10,"rel":0.02},"display":"10 Mbit/s","explanation":"<p>C = B log₂(1 + S/N).</p>"},{"prompt":"<p>Canal de 20 MHz, SNR de 3 (linéaire). Calculez la capacité, en Mbit/s.</p>","unit":"Mbit/s","answer":{"value":40,"rel":0.02},"display":"40 Mbit/s","explanation":"<p>C = B log₂(1 + S/N).</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('numerique:nu-k','final-numerique','Modulations','numeric','[{"prompt":"<p>Combien de bits transporte un symbole à 4 états ?</p>","unit":"bits","answer":{"value":2,"abs":0.1},"display":"2 bits","explanation":"<p>log₂ M.</p>"},{"prompt":"<p>Combien de bits transporte un symbole à 16 états ?</p>","unit":"bits","answer":{"value":4,"abs":0.1},"display":"4 bits","explanation":"<p>log₂ M.</p>"},{"prompt":"<p>Combien de bits transporte un symbole à 64 états ?</p>","unit":"bits","answer":{"value":6,"abs":0.1},"display":"6 bits","explanation":"<p>log₂ M.</p>"},{"prompt":"<p>Combien de bits transporte un symbole à 256 états ?</p>","unit":"bits","answer":{"value":8,"abs":0.1},"display":"8 bits","explanation":"<p>log₂ M.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('numerique:nu-bd','final-numerique','Modulations','numeric','[{"prompt":"<p>Débit de 12 Mbit/s en 16-QAM ou équivalent. Calculez la rapidité, en Mbaud.</p>","unit":"Mbaud","answer":{"value":3,"rel":0.02},"display":"3 Mbaud","explanation":"<p>Rapidité = débit / bits par symbole.</p>"},{"prompt":"<p>Débit de 10 Mbit/s en 4-QAM ou équivalent. Calculez la rapidité, en Mbaud.</p>","unit":"Mbaud","answer":{"value":5,"rel":0.02},"display":"5 Mbaud","explanation":"<p>Rapidité = débit / bits par symbole.</p>"},{"prompt":"<p>Débit de 18 Mbit/s en 64-QAM ou équivalent. Calculez la rapidité, en Mbaud.</p>","unit":"Mbaud","answer":{"value":3,"rel":0.02},"display":"3 Mbaud","explanation":"<p>Rapidité = débit / bits par symbole.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('numerique:nu-ham','final-numerique','Codage','text','[{"prompt":"<p>Encodez les données 1 0 1 1 en Hamming(7,4), avec p₁ = d₁⊕d₂⊕d₄, p₂ = d₁⊕d₃⊕d₄, p₃ = d₂⊕d₃⊕d₄, dans l’ordre p₁ p₂ d₁ p₃ d₂ d₃ d₄. Répondez sur 7 bits.</p>","answer":{"accepted":["0110011"]},"display":"0110011","explanation":"<p>Le mot est 0110011.</p>"},{"prompt":"<p>Encodez les données 0 1 1 0 en Hamming(7,4), avec p₁ = d₁⊕d₂⊕d₄, p₂ = d₁⊕d₃⊕d₄, p₃ = d₂⊕d₃⊕d₄, dans l’ordre p₁ p₂ d₁ p₃ d₂ d₃ d₄. Répondez sur 7 bits.</p>","answer":{"accepted":["1100110"]},"display":"1100110","explanation":"<p>Le mot est 1100110.</p>"},{"prompt":"<p>Encodez les données 1 1 0 0 en Hamming(7,4), avec p₁ = d₁⊕d₂⊕d₄, p₂ = d₁⊕d₃⊕d₄, p₃ = d₂⊕d₃⊕d₄, dans l’ordre p₁ p₂ d₁ p₃ d₂ d₃ d₄. Répondez sur 7 bits.</p>","answer":{"accepted":["0111100"]},"display":"0111100","explanation":"<p>Le mot est 0111100.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('numerique:nu-crc','final-numerique','Codage','qcm','[{"prompt":"<p>Un CRC permet :</p>","options":[{"id":"a","label":"de détecter des erreurs"},{"id":"b","label":"de corriger toutes les erreurs"},{"id":"c","label":"de chiffrer les données"},{"id":"d","label":"de multiplier le débit"}],"answer":{"id":"a"},"display":"de détecter des erreurs","explanation":"<p>Il sert à la détection.</p>"},{"prompt":"<p>Un CRC permet :</p>","options":[{"id":"a","label":"de corriger toutes les erreurs"},{"id":"b","label":"de détecter des erreurs"},{"id":"c","label":"de chiffrer les données"},{"id":"d","label":"de multiplier le débit"}],"answer":{"id":"b"},"display":"de détecter des erreurs","explanation":"<p>Il sert à la détection.</p>"},{"prompt":"<p>Un CRC permet :</p>","options":[{"id":"a","label":"de corriger toutes les erreurs"},{"id":"b","label":"de chiffrer les données"},{"id":"c","label":"de détecter des erreurs"},{"id":"d","label":"de multiplier le débit"}],"answer":{"id":"c"},"display":"de détecter des erreurs","explanation":"<p>Il sert à la détection.</p>"},{"prompt":"<p>Un CRC permet :</p>","options":[{"id":"a","label":"de corriger toutes les erreurs"},{"id":"b","label":"de chiffrer les données"},{"id":"c","label":"de multiplier le débit"},{"id":"d","label":"de détecter des erreurs"}],"answer":{"id":"d"},"display":"de détecter des erreurs","explanation":"<p>Il sert à la détection.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('numerique:nu-man','final-numerique','Codage en ligne','qcm','[{"prompt":"<p>Le code Manchester facilite :</p>","options":[{"id":"a","label":"la récupération de l’horloge"},{"id":"b","label":"la réduction de la bande"},{"id":"c","label":"le chiffrement"},{"id":"d","label":"la compression"}],"answer":{"id":"a"},"display":"la récupération de l’horloge","explanation":"<p>Une transition par bit fournit des repères temporels.</p>"},{"prompt":"<p>Le code Manchester facilite :</p>","options":[{"id":"a","label":"la réduction de la bande"},{"id":"b","label":"la récupération de l’horloge"},{"id":"c","label":"le chiffrement"},{"id":"d","label":"la compression"}],"answer":{"id":"b"},"display":"la récupération de l’horloge","explanation":"<p>Une transition par bit fournit des repères temporels.</p>"},{"prompt":"<p>Le code Manchester facilite :</p>","options":[{"id":"a","label":"la réduction de la bande"},{"id":"b","label":"le chiffrement"},{"id":"c","label":"la récupération de l’horloge"},{"id":"d","label":"la compression"}],"answer":{"id":"c"},"display":"la récupération de l’horloge","explanation":"<p>Une transition par bit fournit des repères temporels.</p>"},{"prompt":"<p>Le code Manchester facilite :</p>","options":[{"id":"a","label":"la réduction de la bande"},{"id":"b","label":"le chiffrement"},{"id":"c","label":"la compression"},{"id":"d","label":"la récupération de l’horloge"}],"answer":{"id":"d"},"display":"la récupération de l’horloge","explanation":"<p>Une transition par bit fournit des repères temporels.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
