insert into private.questions (id,assessment_id,skill,kind,variants) values ('multiplexage:mu-tdm','final-multiplexage','TDM','numeric','[{"prompt":"<p>32 voies de 8 bits, trame de 125 µs. Calculez le débit, en Mbit/s.</p>","unit":"Mbit/s","answer":{"value":2.048,"rel":0.02},"display":"2,048 Mbit/s","explanation":"<p>D = N·b/T.</p>"},{"prompt":"<p>24 voies de 8 bits, trame de 125 µs. Calculez le débit, en Mbit/s.</p>","unit":"Mbit/s","answer":{"value":1.536,"rel":0.02},"display":"1,536 Mbit/s","explanation":"<p>D = N·b/T.</p>"},{"prompt":"<p>16 voies de 8 bits, trame de 125 µs. Calculez le débit, en Mbit/s.</p>","unit":"Mbit/s","answer":{"value":1.024,"rel":0.02},"display":"1,024 Mbit/s","explanation":"<p>D = N·b/T.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('multiplexage:mu-tu','final-multiplexage','OFDM','numeric','[{"prompt":"<p>Espacement de 15 kHz. Calculez T<sub>u</sub>, en µs.</p>","unit":"µs","answer":{"value":66.66666666666667,"rel":0.02},"display":"66,67 µs","explanation":"<p>T<sub>u</sub> = 1/Δf.</p>"},{"prompt":"<p>Espacement de 30 kHz. Calculez T<sub>u</sub>, en µs.</p>","unit":"µs","answer":{"value":33.333333333333336,"rel":0.02},"display":"33,33 µs","explanation":"<p>T<sub>u</sub> = 1/Δf.</p>"},{"prompt":"<p>Espacement de 60 kHz. Calculez T<sub>u</sub>, en µs.</p>","unit":"µs","answer":{"value":16.666666666666668,"rel":0.02},"display":"16,67 µs","explanation":"<p>T<sub>u</sub> = 1/Δf.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('multiplexage:mu-b','final-multiplexage','OFDM','numeric','[{"prompt":"<p>3276 sous-porteuses espacées de 30 kHz. Calculez la bande, en MHz.</p>","unit":"MHz","answer":{"value":98.28,"rel":0.02},"display":"98,28 MHz","explanation":"<p>B = N·Δf.</p>"},{"prompt":"<p>1200 sous-porteuses espacées de 15 kHz. Calculez la bande, en MHz.</p>","unit":"MHz","answer":{"value":18,"rel":0.02},"display":"18 MHz","explanation":"<p>B = N·Δf.</p>"},{"prompt":"<p>600 sous-porteuses espacées de 15 kHz. Calculez la bande, en MHz.</p>","unit":"MHz","answer":{"value":9,"rel":0.02},"display":"9 MHz","explanation":"<p>B = N·Δf.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('multiplexage:mu-al','final-multiplexage','Accès aléatoire','numeric','[{"prompt":"<p>G = 0,5 en ALOHA à créneaux. Calculez S.</p>","unit":"","answer":{"value":0.3032653298563167,"rel":0.02},"display":"0,3033","explanation":"<p>S = G e<sup>−G</sup>.</p>"},{"prompt":"<p>G = 1 en ALOHA à créneaux. Calculez S.</p>","unit":"","answer":{"value":0.36787944117144233,"rel":0.02},"display":"0,3679","explanation":"<p>S = G e<sup>−G</sup>.</p>"},{"prompt":"<p>G = 2 en ALOHA à créneaux. Calculez S.</p>","unit":"","answer":{"value":0.2706705664732254,"rel":0.02},"display":"0,2707","explanation":"<p>S = G e<sup>−G</sup>.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
