insert into private.questions (id,assessment_id,skill,kind,variants) values ('multiplexage:mu-wdm','final-multiplexage','Multiplexage','qcm','[{"prompt":"<p>Le WDM est utilisé :</p>","options":[{"id":"a","label":"sur les fibres optiques"},{"id":"b","label":"sur les câbles téléphoniques uniquement"},{"id":"c","label":"dans les bus de processeur"},{"id":"d","label":"dans les diodes Zener"}],"answer":{"id":"a"},"display":"sur les fibres optiques","explanation":"<p>Plusieurs longueurs d’onde sur une fibre.</p>"},{"prompt":"<p>Le WDM est utilisé :</p>","options":[{"id":"a","label":"sur les câbles téléphoniques uniquement"},{"id":"b","label":"sur les fibres optiques"},{"id":"c","label":"dans les bus de processeur"},{"id":"d","label":"dans les diodes Zener"}],"answer":{"id":"b"},"display":"sur les fibres optiques","explanation":"<p>Plusieurs longueurs d’onde sur une fibre.</p>"},{"prompt":"<p>Le WDM est utilisé :</p>","options":[{"id":"a","label":"sur les câbles téléphoniques uniquement"},{"id":"b","label":"dans les bus de processeur"},{"id":"c","label":"sur les fibres optiques"},{"id":"d","label":"dans les diodes Zener"}],"answer":{"id":"c"},"display":"sur les fibres optiques","explanation":"<p>Plusieurs longueurs d’onde sur une fibre.</p>"},{"prompt":"<p>Le WDM est utilisé :</p>","options":[{"id":"a","label":"sur les câbles téléphoniques uniquement"},{"id":"b","label":"dans les bus de processeur"},{"id":"c","label":"dans les diodes Zener"},{"id":"d","label":"sur les fibres optiques"}],"answer":{"id":"d"},"display":"sur les fibres optiques","explanation":"<p>Plusieurs longueurs d’onde sur une fibre.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
