insert into private.questions (id,assessment_id,skill,kind,variants) values ('fibre:fi-crit','final-fibre','Réflexion totale','numeric','[{"prompt":"<p>Cœur n₁ = 1,48, gaine n₂ = 1,46. Calculez l’angle critique, en degrés.</p>","unit":"°","answer":{"value":80.56999209210358,"abs":0.15},"display":"80,57 °","explanation":"<p>θc = arcsin(n₂/n₁) = 80,57°.</p>"},{"prompt":"<p>Cœur n₁ = 1,5, gaine n₂ = 1,48. Calculez l’angle critique, en degrés.</p>","unit":"°","answer":{"value":80.6332111156484,"abs":0.15},"display":"80,63 °","explanation":"<p>θc = arcsin(n₂/n₁) = 80,63°.</p>"},{"prompt":"<p>Cœur n₁ = 1,468, gaine n₂ = 1,462. Calculez l’angle critique, en degrés.</p>","unit":"°","answer":{"value":85.12900925606117,"abs":0.15},"display":"85,13 °","explanation":"<p>θc = arcsin(n₂/n₁) = 85,13°.</p>"},{"prompt":"<p>Cœur n₁ = 1,47, gaine n₂ = 1,45. Calculez l’angle critique, en degrés.</p>","unit":"°","answer":{"value":80.5378987509266,"abs":0.15},"display":"80,54 °","explanation":"<p>θc = arcsin(n₂/n₁) = 80,54°.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('fibre:fi-na','final-fibre','Ouverture numérique','numeric','[{"prompt":"<p>Calculez l’ouverture numérique pour n₁ = 1,48 et n₂ = 1,46.</p>","unit":"","answer":{"value":0.2424871130596432,"abs":0.006},"display":"0,2425","explanation":"<p>ON = √(n₁² − n₂²) = 0,2425.</p>"},{"prompt":"<p>Calculez l’ouverture numérique pour n₁ = 1,5 et n₂ = 1,48.</p>","unit":"","answer":{"value":0.24413111231467427,"abs":0.006},"display":"0,2441","explanation":"<p>ON = √(n₁² − n₂²) = 0,2441.</p>"},{"prompt":"<p>Calculez l’ouverture numérique pour n₁ = 1,47 et n₂ = 1,45.</p>","unit":"","answer":{"value":0.241660919471891,"abs":0.006},"display":"0,2417","explanation":"<p>ON = √(n₁² − n₂²) = 0,2417.</p>"},{"prompt":"<p>Calculez l’ouverture numérique pour n₁ = 1,46 et n₂ = 1,44.</p>","unit":"","answer":{"value":0.24083189157584556,"abs":0.006},"display":"0,2408","explanation":"<p>ON = √(n₁² − n₂²) = 0,2408.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('fibre:fi-budget','final-fibre','Bilan de puissance','numeric','[{"prompt":"<p>Puissance émise 0 dBm, fibre 0,2 dB/km sur 80 km, 3 épissure(s) à 0,1 dB, 2 connecteur(s) à 0,5 dB. Calculez la puissance reçue, en dBm.</p>","unit":"dBm","answer":{"value":-17.3,"abs":0.1},"display":"−17,3 dBm","explanation":"<p>Pertes totales 17,3 dB, donc Pr = −17,3 dBm.</p>"},{"prompt":"<p>Puissance émise −3 dBm, fibre 0,35 dB/km sur 40 km, 2 épissure(s) à 0,1 dB, 2 connecteur(s) à 0,5 dB. Calculez la puissance reçue, en dBm.</p>","unit":"dBm","answer":{"value":-18.2,"abs":0.1},"display":"−18,2 dBm","explanation":"<p>Pertes totales 15,2 dB, donc Pr = −18,2 dBm.</p>"},{"prompt":"<p>Puissance émise 3 dBm, fibre 0,25 dB/km sur 60 km, 5 épissure(s) à 0,1 dB, 4 connecteur(s) à 0,5 dB. Calculez la puissance reçue, en dBm.</p>","unit":"dBm","answer":{"value":-14.5,"abs":0.1},"display":"−14,5 dBm","explanation":"<p>Pertes totales 17,5 dB, donc Pr = −14,5 dBm.</p>"},{"prompt":"<p>Puissance émise 0 dBm, fibre 3 dB/km sur 2 km, 0 épissure(s) à 0,1 dB, 2 connecteur(s) à 0,5 dB. Calculez la puissance reçue, en dBm.</p>","unit":"dBm","answer":{"value":-7,"abs":0.1},"display":"−7 dBm","explanation":"<p>Pertes totales 7 dB, donc Pr = −7 dBm.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('fibre:fi-max','final-fibre','Bilan de puissance','numeric','[{"prompt":"<p>Puissance émise 0 dBm, sensibilité −28 dBm, 0,2 dB/km, 3 épissure(s) à 0,1 dB, 2 connecteur(s) à 0,5 dB. Calculez la longueur maximale, en km.</p>","unit":"km","answer":{"value":133.5,"rel":0.02},"display":"133,5 km","explanation":"<p>L = (Pe − S − raccordements)/α = 133,5 km.</p>"},{"prompt":"<p>Puissance émise 3 dBm, sensibilité −24 dBm, 0,35 dB/km, 2 épissure(s) à 0,1 dB, 2 connecteur(s) à 0,5 dB. Calculez la longueur maximale, en km.</p>","unit":"km","answer":{"value":73.71428571428572,"rel":0.02},"display":"73,71 km","explanation":"<p>L = (Pe − S − raccordements)/α = 73,71 km.</p>"},{"prompt":"<p>Puissance émise −3 dBm, sensibilité −30 dBm, 0,25 dB/km, 4 épissure(s) à 0,1 dB, 4 connecteur(s) à 0,5 dB. Calculez la longueur maximale, en km.</p>","unit":"km","answer":{"value":98.4,"rel":0.02},"display":"98,4 km","explanation":"<p>L = (Pe − S − raccordements)/α = 98,4 km.</p>"},{"prompt":"<p>Puissance émise 0 dBm, sensibilité −20 dBm, 0,5 dB/km, 0 épissure(s) à 0,1 dB, 2 connecteur(s) à 0,5 dB. Calculez la longueur maximale, en km.</p>","unit":"km","answer":{"value":38,"rel":0.02},"display":"38 km","explanation":"<p>L = (Pe − S − raccordements)/α = 38 km.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('fibre:fi-depannage','final-fibre','Dépannage','qcm','[{"prompt":"<p>Scénario de dépannage : une liaison optique neuve présente 4 dB de pertes de plus que prévu, concentrés en un seul point du tracé OTDR. Quelle est la cause la plus probable ?</p>","options":[{"id":"a","label":"Une épissure ou un connecteur défectueux à cet endroit"},{"id":"b","label":"L’atténuation linéique de la fibre est trop forte"},{"id":"c","label":"La longueur d’onde du laser est trop courte"},{"id":"d","label":"La sensibilité du récepteur est insuffisante"}],"answer":{"id":"a"},"display":"Une épissure ou un connecteur défectueux à cet endroit","explanation":"<p>Une perte localisée se voit comme une marche sur la trace OTDR ; une atténuation trop forte modifierait la pente sur toute la longueur.</p>"},{"prompt":"<p>Scénario de dépannage : une liaison optique neuve présente 4 dB de pertes de plus que prévu, concentrés en un seul point du tracé OTDR. Quelle est la cause la plus probable ?</p>","options":[{"id":"a","label":"L’atténuation linéique de la fibre est trop forte"},{"id":"b","label":"Une épissure ou un connecteur défectueux à cet endroit"},{"id":"c","label":"La longueur d’onde du laser est trop courte"},{"id":"d","label":"La sensibilité du récepteur est insuffisante"}],"answer":{"id":"b"},"display":"Une épissure ou un connecteur défectueux à cet endroit","explanation":"<p>Une perte localisée se voit comme une marche sur la trace OTDR ; une atténuation trop forte modifierait la pente sur toute la longueur.</p>"},{"prompt":"<p>Scénario de dépannage : une liaison optique neuve présente 4 dB de pertes de plus que prévu, concentrés en un seul point du tracé OTDR. Quelle est la cause la plus probable ?</p>","options":[{"id":"a","label":"L’atténuation linéique de la fibre est trop forte"},{"id":"b","label":"La longueur d’onde du laser est trop courte"},{"id":"c","label":"Une épissure ou un connecteur défectueux à cet endroit"},{"id":"d","label":"La sensibilité du récepteur est insuffisante"}],"answer":{"id":"c"},"display":"Une épissure ou un connecteur défectueux à cet endroit","explanation":"<p>Une perte localisée se voit comme une marche sur la trace OTDR ; une atténuation trop forte modifierait la pente sur toute la longueur.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
