insert into private.questions (id,assessment_id,skill,kind,variants) values ('satellite:sa-t','final-satellite','Orbites','numeric','[{"prompt":"<p>Calculez la période d’une orbite circulaire à 500 km, en minutes.</p>","unit":"min","answer":{"value":94.61630047543098,"rel":0.02},"display":"94,62 min","explanation":"<p>T = 2π√(a³/µ).</p>"},{"prompt":"<p>Calculez la période d’une orbite circulaire à 1200 km, en minutes.</p>","unit":"min","answer":{"value":109.42168760616133,"rel":0.02},"display":"109,4 min","explanation":"<p>T = 2π√(a³/µ).</p>"},{"prompt":"<p>Calculez la période d’une orbite circulaire à 20200 km, en minutes.</p>","unit":"min","answer":{"value":718.6981611502525,"rel":0.02},"display":"718,7 min","explanation":"<p>T = 2π√(a³/µ).</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('satellite:sa-v','final-satellite','Orbites','numeric','[{"prompt":"<p>Calculez la vitesse orbitale à 500 km, en km/s.</p>","unit":"km/s","answer":{"value":7.612608173223869,"rel":0.02},"display":"7,613 km/s","explanation":"<p>v = √(µ/a).</p>"},{"prompt":"<p>Calculez la vitesse orbitale à 1200 km, en km/s.</p>","unit":"km/s","answer":{"value":7.252498734616008,"rel":0.02},"display":"7,252 km/s","explanation":"<p>v = √(µ/a).</p>"},{"prompt":"<p>Calculez la vitesse orbitale à 35786 km, en km/s.</p>","unit":"km/s","answer":{"value":3.0746612890103515,"rel":0.02},"display":"3,075 km/s","explanation":"<p>v = √(µ/a).</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('satellite:sa-l','final-satellite','Bilan','numeric','[{"prompt":"<p>d = 1000 km, f = 12 GHz. Calculez l’affaiblissement en espace libre, en dB.</p>","unit":"dB","answer":{"value":174.0336249209525,"abs":0.3},"display":"174 dB","explanation":"<p>L = 92,45 + 20 log₁₀ d + 20 log₁₀ f.</p>"},{"prompt":"<p>d = 36000 km, f = 4 GHz. Calculez l’affaiblissement en espace libre, en dB.</p>","unit":"dB","answer":{"value":195.617249841905,"abs":0.3},"display":"195,6 dB","explanation":"<p>L = 92,45 + 20 log₁₀ d + 20 log₁₀ f.</p>"},{"prompt":"<p>d = 550 km, f = 20 GHz. Calculez l’affaiblissement en espace libre, en dB.</p>","unit":"dB","answer":{"value":173.2778537031645,"abs":0.3},"display":"173,3 dB","explanation":"<p>L = 92,45 + 20 log₁₀ d + 20 log₁₀ f.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('satellite:sa-cn','final-satellite','Bilan','numeric','[{"prompt":"<p>EIRP = 50 dBW, L = 205 dB, G/T = 20 dB/K. Calculez C/N₀, en dB·Hz.</p>","unit":"dB·Hz","answer":{"value":93.59916717321764,"abs":0.2},"display":"93,6 dB·Hz","explanation":"<p>C/N₀ = EIRP − L + G/T + 228,6.</p>"},{"prompt":"<p>EIRP = 40 dBW, L = 180 dB, G/T = 10 dB/K. Calculez C/N₀, en dB·Hz.</p>","unit":"dB·Hz","answer":{"value":98.59916717321764,"abs":0.2},"display":"98,6 dB·Hz","explanation":"<p>C/N₀ = EIRP − L + G/T + 228,6.</p>"},{"prompt":"<p>EIRP = 52 dBW, L = 206 dB, G/T = 25 dB/K. Calculez C/N₀, en dB·Hz.</p>","unit":"dB·Hz","answer":{"value":99.59916717321764,"abs":0.2},"display":"99,6 dB·Hz","explanation":"<p>C/N₀ = EIRP − L + G/T + 228,6.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
