insert into private.questions (id,assessment_id,skill,kind,variants) values ('satellite:sa-geo','final-satellite','Orbites','qcm','[{"prompt":"<p>Un satellite géostationnaire est placé à environ :</p>","options":[{"id":"a","label":"35 786 km"},{"id":"b","label":"550 km"},{"id":"c","label":"2 000 km"},{"id":"d","label":"384 000 km"}],"answer":{"id":"a"},"display":"35 786 km","explanation":"<p>À cette altitude, la période égale un jour sidéral.</p>"},{"prompt":"<p>Un satellite géostationnaire est placé à environ :</p>","options":[{"id":"a","label":"550 km"},{"id":"b","label":"35 786 km"},{"id":"c","label":"2 000 km"},{"id":"d","label":"384 000 km"}],"answer":{"id":"b"},"display":"35 786 km","explanation":"<p>À cette altitude, la période égale un jour sidéral.</p>"},{"prompt":"<p>Un satellite géostationnaire est placé à environ :</p>","options":[{"id":"a","label":"550 km"},{"id":"b","label":"2 000 km"},{"id":"c","label":"35 786 km"},{"id":"d","label":"384 000 km"}],"answer":{"id":"c"},"display":"35 786 km","explanation":"<p>À cette altitude, la période égale un jour sidéral.</p>"},{"prompt":"<p>Un satellite géostationnaire est placé à environ :</p>","options":[{"id":"a","label":"550 km"},{"id":"b","label":"2 000 km"},{"id":"c","label":"384 000 km"},{"id":"d","label":"35 786 km"}],"answer":{"id":"d"},"display":"35 786 km","explanation":"<p>À cette altitude, la période égale un jour sidéral.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
