insert into private.questions (id,assessment_id,skill,kind,variants) values ('sans-fil:sf-l','final-sans-fil','Couverture','numeric','[{"prompt":"<p>f = 2437 MHz, d = 10 m, n = 3, sans mur. Calculez L, en dB.</p>","unit":"dB","answer":{"value":70.18711058369448,"abs":0.5},"display":"70,19 dB","explanation":"<p>L = 20 log₁₀ f − 27,55 + 10n log₁₀ d.</p>"},{"prompt":"<p>f = 2437 MHz, d = 20 m, n = 3, sans mur. Calculez L, en dB.</p>","unit":"dB","answer":{"value":79.21801045361391,"abs":0.5},"display":"79,22 dB","explanation":"<p>L = 20 log₁₀ f − 27,55 + 10n log₁₀ d.</p>"},{"prompt":"<p>f = 2437 MHz, d = 15 m, n = 2.5, sans mur. Calculez L, en dB.</p>","unit":"dB","answer":{"value":69.58939206008651,"abs":0.5},"display":"69,59 dB","explanation":"<p>L = 20 log₁₀ f − 27,55 + 10n log₁₀ d.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('sans-fil:sf-r','final-sans-fil','Couverture','numeric','[{"prompt":"<p>20 MHz, SNR 30 dB. Calculez la limite de Shannon, en Mbit/s.</p>","unit":"Mbit/s","answer":{"value":199.34452517671986,"rel":0.02},"display":"199,3 Mbit/s","explanation":"<p>C = B log₂(1 + S/N).</p>"},{"prompt":"<p>40 MHz, SNR 25 dB. Calculez la limite de Shannon, en Mbit/s.</p>","unit":"Mbit/s","answer":{"value":332.3750096485122,"rel":0.02},"display":"332,4 Mbit/s","explanation":"<p>C = B log₂(1 + S/N).</p>"},{"prompt":"<p>20 MHz, SNR 10 dB. Calculez la limite de Shannon, en Mbit/s.</p>","unit":"Mbit/s","answer":{"value":69.18863237274594,"rel":0.02},"display":"69,19 Mbit/s","explanation":"<p>C = B log₂(1 + S/N).</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('sans-fil:sf-p','final-sans-fil','Accès','numeric','[{"prompt":"<p>W = 16, n = 2 stations. Calculez p<sub>c</sub>.</p>","unit":"","answer":{"value":0.0625,"rel":0.02},"display":"0,0625","explanation":"<p>p<sub>c</sub> = 1 − (1 − 1/W)<sup>n−1</sup>.</p>"},{"prompt":"<p>W = 16, n = 10 stations. Calculez p<sub>c</sub>.</p>","unit":"","answer":{"value":0.4405754932813579,"rel":0.02},"display":"0,4406","explanation":"<p>p<sub>c</sub> = 1 − (1 − 1/W)<sup>n−1</sup>.</p>"},{"prompt":"<p>W = 32, n = 5 stations. Calculez p<sub>c</sub>.</p>","unit":"","answer":{"value":0.1192617416381836,"rel":0.02},"display":"0,1193","explanation":"<p>p<sub>c</sub> = 1 − (1 − 1/W)<sup>n−1</sup>.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('sans-fil:sf-ch','final-sans-fil','Canaux','qcm','[{"prompt":"<p>Quel trio est disjoint à 2,4 GHz ?</p>","options":[{"id":"a","label":"1, 6 et 11"},{"id":"b","label":"1, 2 et 3"},{"id":"c","label":"2, 4 et 6"},{"id":"d","label":"5, 7 et 9"}],"answer":{"id":"a"},"display":"1, 6 et 11","explanation":"<p>Il faut au moins 25 MHz d’écart.</p>"},{"prompt":"<p>Quel trio est disjoint à 2,4 GHz ?</p>","options":[{"id":"a","label":"1, 2 et 3"},{"id":"b","label":"1, 6 et 11"},{"id":"c","label":"2, 4 et 6"},{"id":"d","label":"5, 7 et 9"}],"answer":{"id":"b"},"display":"1, 6 et 11","explanation":"<p>Il faut au moins 25 MHz d’écart.</p>"},{"prompt":"<p>Quel trio est disjoint à 2,4 GHz ?</p>","options":[{"id":"a","label":"1, 2 et 3"},{"id":"b","label":"2, 4 et 6"},{"id":"c","label":"1, 6 et 11"},{"id":"d","label":"5, 7 et 9"}],"answer":{"id":"c"},"display":"1, 6 et 11","explanation":"<p>Il faut au moins 25 MHz d’écart.</p>"},{"prompt":"<p>Quel trio est disjoint à 2,4 GHz ?</p>","options":[{"id":"a","label":"1, 2 et 3"},{"id":"b","label":"2, 4 et 6"},{"id":"c","label":"5, 7 et 9"},{"id":"d","label":"1, 6 et 11"}],"answer":{"id":"d"},"display":"1, 6 et 11","explanation":"<p>Il faut au moins 25 MHz d’écart.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
