insert into private.questions (id,assessment_id,skill,kind,variants) values ('qualite:qu-noise','final-qualite','Bruit','numeric','[{"prompt":"<p>Calculez le bruit thermique à 290 K dans 1 MHz, en dBm.</p>","unit":"dBm","answer":{"value":-113.97518719422808,"abs":0.3},"display":"−114 dBm","explanation":"<p>N = 10 log₁₀(kTB/1 mW).</p>"},{"prompt":"<p>Calculez le bruit thermique à 290 K dans 20 MHz, en dBm.</p>","unit":"dBm","answer":{"value":-100.9648872375883,"abs":0.3},"display":"−101 dBm","explanation":"<p>N = 10 log₁₀(kTB/1 mW).</p>"},{"prompt":"<p>Calculez le bruit thermique à 290 K dans 100 kHz, en dBm.</p>","unit":"dBm","answer":{"value":-123.97518719422808,"abs":0.3},"display":"−124 dBm","explanation":"<p>N = 10 log₁₀(kTB/1 mW).</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('qualite:qu-friis','final-qualite','Bruit','numeric','[{"prompt":"<p>LNA : gain 15 dB, NF 2 dB ; mélangeur NF 8 dB. Calculez le NF total, en dB.</p>","unit":"dB","answer":{"value":2.43731533861159,"abs":0.15},"display":"2,437 dB","explanation":"<p>F = F₁ + (F₂ − 1)/G₁.</p>"},{"prompt":"<p>LNA : gain 20 dB, NF 1 dB ; mélangeur NF 10 dB. Calculez le NF total, en dB.</p>","unit":"dB","answer":{"value":1.299879362235896,"abs":0.15},"display":"1,3 dB","explanation":"<p>F = F₁ + (F₂ − 1)/G₁.</p>"},{"prompt":"<p>LNA : gain 10 dB, NF 3 dB ; mélangeur NF 12 dB. Calculez le NF total, en dB.</p>","unit":"dB","answer":{"value":5.4159865041492194,"abs":0.15},"display":"5,416 dB","explanation":"<p>F = F₁ + (F₂ − 1)/G₁.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('qualite:qu-evm','final-qualite','Œil et EVM','numeric','[{"prompt":"<p>EVM de 10 %. Calculez sa valeur en dB.</p>","unit":"dB","answer":{"value":-19.999999999999996,"abs":0.15},"display":"−20 dB","explanation":"<p>EVM<sub>dB</sub> = 20 log₁₀(EVM<sub>%</sub>/100).</p>"},{"prompt":"<p>EVM de 5 %. Calculez sa valeur en dB.</p>","unit":"dB","answer":{"value":-26.02059991327962,"abs":0.15},"display":"−26,02 dB","explanation":"<p>EVM<sub>dB</sub> = 20 log₁₀(EVM<sub>%</sub>/100).</p>"},{"prompt":"<p>EVM de 1 %. Calculez sa valeur en dB.</p>","unit":"dB","answer":{"value":-39.99999999999999,"abs":0.15},"display":"−40 dB","explanation":"<p>EVM<sub>dB</sub> = 20 log₁₀(EVM<sub>%</sub>/100).</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('qualite:qu-first','final-qualite','Bruit','qcm','[{"prompt":"<p>Dans une cascade, l’étage qui compte le plus pour le bruit est :</p>","options":[{"id":"a","label":"le premier"},{"id":"b","label":"le dernier"},{"id":"c","label":"celui du milieu"},{"id":"d","label":"aucun"}],"answer":{"id":"a"},"display":"le premier","explanation":"<p>La contribution des suivants est divisée par le gain des précédents.</p>"},{"prompt":"<p>Dans une cascade, l’étage qui compte le plus pour le bruit est :</p>","options":[{"id":"a","label":"le dernier"},{"id":"b","label":"le premier"},{"id":"c","label":"celui du milieu"},{"id":"d","label":"aucun"}],"answer":{"id":"b"},"display":"le premier","explanation":"<p>La contribution des suivants est divisée par le gain des précédents.</p>"},{"prompt":"<p>Dans une cascade, l’étage qui compte le plus pour le bruit est :</p>","options":[{"id":"a","label":"le dernier"},{"id":"b","label":"celui du milieu"},{"id":"c","label":"le premier"},{"id":"d","label":"aucun"}],"answer":{"id":"c"},"display":"le premier","explanation":"<p>La contribution des suivants est divisée par le gain des précédents.</p>"},{"prompt":"<p>Dans une cascade, l’étage qui compte le plus pour le bruit est :</p>","options":[{"id":"a","label":"le dernier"},{"id":"b","label":"celui du milieu"},{"id":"c","label":"aucun"},{"id":"d","label":"le premier"}],"answer":{"id":"d"},"display":"le premier","explanation":"<p>La contribution des suivants est divisée par le gain des précédents.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('qualite:qu-eye','final-qualite','Œil et EVM','qcm','[{"prompt":"<p>Un œil bien ouvert indique :</p>","options":[{"id":"a","label":"une décision fiable au récepteur"},{"id":"b","label":"une panne de l’émetteur"},{"id":"c","label":"une fréquence nulle"},{"id":"d","label":"une alimentation trop faible"}],"answer":{"id":"a"},"display":"une décision fiable au récepteur","explanation":"<p>Les niveaux restent bien séparés à l’instant de décision.</p>"},{"prompt":"<p>Un œil bien ouvert indique :</p>","options":[{"id":"a","label":"une panne de l’émetteur"},{"id":"b","label":"une décision fiable au récepteur"},{"id":"c","label":"une fréquence nulle"},{"id":"d","label":"une alimentation trop faible"}],"answer":{"id":"b"},"display":"une décision fiable au récepteur","explanation":"<p>Les niveaux restent bien séparés à l’instant de décision.</p>"},{"prompt":"<p>Un œil bien ouvert indique :</p>","options":[{"id":"a","label":"une panne de l’émetteur"},{"id":"b","label":"une fréquence nulle"},{"id":"c","label":"une décision fiable au récepteur"},{"id":"d","label":"une alimentation trop faible"}],"answer":{"id":"c"},"display":"une décision fiable au récepteur","explanation":"<p>Les niveaux restent bien séparés à l’instant de décision.</p>"},{"prompt":"<p>Un œil bien ouvert indique :</p>","options":[{"id":"a","label":"une panne de l’émetteur"},{"id":"b","label":"une fréquence nulle"},{"id":"c","label":"une alimentation trop faible"},{"id":"d","label":"une décision fiable au récepteur"}],"answer":{"id":"d"},"display":"une décision fiable au récepteur","explanation":"<p>Les niveaux restent bien séparés à l’instant de décision.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
