insert into private.questions (id,assessment_id,skill,kind,variants) values ('ingenierie:in-a','final-ingenierie','Trafic','numeric','[{"prompt":"<p>300 appels par heure de 180 s. Calculez le trafic, en Erlang.</p>","unit":"Erl","answer":{"value":15,"rel":0.02},"display":"15 Erl","explanation":"<p>A = λ·h.</p>"},{"prompt":"<p>600 appels par heure de 120 s. Calculez le trafic, en Erlang.</p>","unit":"Erl","answer":{"value":20,"rel":0.02},"display":"20 Erl","explanation":"<p>A = λ·h.</p>"},{"prompt":"<p>1800 appels par heure de 120 s. Calculez le trafic, en Erlang.</p>","unit":"Erl","answer":{"value":60,"rel":0.02},"display":"60 Erl","explanation":"<p>A = λ·h.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('ingenierie:in-b','final-ingenierie','Trafic','numeric','[{"prompt":"<p>A = 2 Erlangs, 3 circuits. Calculez le blocage, en %.</p>","unit":"%","answer":{"value":21.052631578947366,"rel":0.02},"display":"21,05 %","explanation":"<p>Formule Erlang B.</p>"},{"prompt":"<p>A = 5 Erlangs, 8 circuits. Calculez le blocage, en %.</p>","unit":"%","answer":{"value":7.004785220956704,"rel":0.02},"display":"7,005 %","explanation":"<p>Formule Erlang B.</p>"},{"prompt":"<p>A = 10 Erlangs, 15 circuits. Calculez le blocage, en %.</p>","unit":"%","answer":{"value":3.6496945472370785,"rel":0.02},"display":"3,65 %","explanation":"<p>Formule Erlang B.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('ingenierie:in-m','final-ingenierie','Trafic','numeric','[{"prompt":"<p>A = 10 Erlangs, blocage visé 1 %. Combien de circuits ?</p>","unit":"","answer":{"value":18,"abs":0.5},"display":"18","explanation":"<p>Plus petit m tel que B(A, m) ≤ cible.</p>"},{"prompt":"<p>A = 5 Erlangs, blocage visé 2 %. Combien de circuits ?</p>","unit":"","answer":{"value":10,"abs":0.5},"display":"10","explanation":"<p>Plus petit m tel que B(A, m) ≤ cible.</p>"},{"prompt":"<p>A = 20 Erlangs, blocage visé 1 %. Combien de circuits ?</p>","unit":"","answer":{"value":30,"abs":0.5},"display":"30","explanation":"<p>Plus petit m tel que B(A, m) ≤ cible.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('ingenierie:in-av','final-ingenierie','Disponibilité','numeric','[{"prompt":"<p>MTBF = 1000 h, MTTR = 2 h. Calculez la disponibilité, en %.</p>","unit":"%","answer":{"value":99.8003992015968,"abs":0.05},"display":"99,8 %","explanation":"<p>A = MTBF/(MTBF + MTTR).</p>"},{"prompt":"<p>MTBF = 8760 h, MTTR = 24 h. Calculez la disponibilité, en %.</p>","unit":"%","answer":{"value":99.72677595628416,"abs":0.05},"display":"99,73 %","explanation":"<p>A = MTBF/(MTBF + MTTR).</p>"},{"prompt":"<p>MTBF = 500 h, MTTR = 5 h. Calculez la disponibilité, en %.</p>","unit":"%","answer":{"value":99.00990099009901,"abs":0.05},"display":"99,01 %","explanation":"<p>A = MTBF/(MTBF + MTTR).</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('ingenierie:in-par','final-ingenierie','Disponibilité','numeric','[{"prompt":"<p>2 éléments disponibles à 95 % en parallèle. Calculez la disponibilité, en %.</p>","unit":"%","answer":{"value":99.75,"abs":0.02},"display":"99,75 %","explanation":"<p>A = 1 − (1 − a)<sup>n</sup>.</p>"},{"prompt":"<p>2 éléments disponibles à 99 % en parallèle. Calculez la disponibilité, en %.</p>","unit":"%","answer":{"value":99.99,"abs":0.02},"display":"99,99 %","explanation":"<p>A = 1 − (1 − a)<sup>n</sup>.</p>"},{"prompt":"<p>3 éléments disponibles à 90 % en parallèle. Calculez la disponibilité, en %.</p>","unit":"%","answer":{"value":99.9,"abs":0.02},"display":"99,9 %","explanation":"<p>A = 1 − (1 − a)<sup>n</sup>.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('ingenierie:in-busy','final-ingenierie','Trafic','qcm','[{"prompt":"<p>Un réseau se dimensionne d’après :</p>","options":[{"id":"a","label":"l’heure chargée"},{"id":"b","label":"la moyenne annuelle"},{"id":"c","label":"la nuit"},{"id":"d","label":"le week-end"}],"answer":{"id":"a"},"display":"l’heure chargée","explanation":"<p>Il doit écouler le trafic de pointe.</p>"},{"prompt":"<p>Un réseau se dimensionne d’après :</p>","options":[{"id":"a","label":"la moyenne annuelle"},{"id":"b","label":"l’heure chargée"},{"id":"c","label":"la nuit"},{"id":"d","label":"le week-end"}],"answer":{"id":"b"},"display":"l’heure chargée","explanation":"<p>Il doit écouler le trafic de pointe.</p>"},{"prompt":"<p>Un réseau se dimensionne d’après :</p>","options":[{"id":"a","label":"la moyenne annuelle"},{"id":"b","label":"la nuit"},{"id":"c","label":"l’heure chargée"},{"id":"d","label":"le week-end"}],"answer":{"id":"c"},"display":"l’heure chargée","explanation":"<p>Il doit écouler le trafic de pointe.</p>"},{"prompt":"<p>Un réseau se dimensionne d’après :</p>","options":[{"id":"a","label":"la moyenne annuelle"},{"id":"b","label":"la nuit"},{"id":"c","label":"le week-end"},{"id":"d","label":"l’heure chargée"}],"answer":{"id":"d"},"display":"l’heure chargée","explanation":"<p>Il doit écouler le trafic de pointe.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into public.assessments (id,title,description,kind,competency,question_count,pass_percent,duration_seconds,max_attempts,cooldown_minutes,prerequisites,grants,status) values ('final-circuits','Évaluation : Circuits électriques','Évaluation de fin de module, corrigée par le serveur.','course_final','circuits',5,70,1200,null,30,array[]::text[],array[]::text[],'published') on conflict (id) do update set title=excluded.title, description=excluded.description, prerequisites=excluded.prerequisites, grants=excluded.grants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('circuits:ci-ohm','final-circuits','Loi d’Ohm','numeric','[{"prompt":"<p>Une résistance de 470 Ω est alimentée sous 12 V. Calculez le courant, <strong>en mA</strong>.</p>","unit":"mA","answer":{"value":25.53191489361702,"rel":0.02},"display":"25,53 mA","explanation":"<p>I = U/R = 12 / 470 = 25,53 mA.</p>"},{"prompt":"<p>Une résistance de 220 Ω est alimentée sous 5 V. Calculez le courant, <strong>en mA</strong>.</p>","unit":"mA","answer":{"value":22.727272727272727,"rel":0.02},"display":"22,73 mA","explanation":"<p>I = U/R = 5 / 220 = 22,73 mA.</p>"},{"prompt":"<p>Une résistance de 1 000 Ω est alimentée sous 9 V. Calculez le courant, <strong>en mA</strong>.</p>","unit":"mA","answer":{"value":9,"rel":0.02},"display":"9 mA","explanation":"<p>I = U/R = 9 / 1 000 = 9 mA.</p>"},{"prompt":"<p>Une résistance de 680 Ω est alimentée sous 24 V. Calculez le courant, <strong>en mA</strong>.</p>","unit":"mA","answer":{"value":35.294117647058826,"rel":0.02},"display":"35,29 mA","explanation":"<p>I = U/R = 24 / 680 = 35,29 mA.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('circuits:ci-par','final-circuits','Association de résistances','numeric','[{"prompt":"<p>Deux résistances de 100 Ω et 100 Ω sont en parallèle. Calculez la résistance équivalente, en Ω.</p>","unit":"Ω","answer":{"value":50,"rel":0.02},"display":"50 Ω","explanation":"<p>Req = R₁R₂/(R₁+R₂) = 50 Ω.</p>"},{"prompt":"<p>Deux résistances de 220 Ω et 330 Ω sont en parallèle. Calculez la résistance équivalente, en Ω.</p>","unit":"Ω","answer":{"value":132,"rel":0.02},"display":"132 Ω","explanation":"<p>Req = R₁R₂/(R₁+R₂) = 132 Ω.</p>"},{"prompt":"<p>Deux résistances de 1 000 Ω et 470 Ω sont en parallèle. Calculez la résistance équivalente, en Ω.</p>","unit":"Ω","answer":{"value":319.7278911564626,"rel":0.02},"display":"319,7 Ω","explanation":"<p>Req = R₁R₂/(R₁+R₂) = 319,7 Ω.</p>"},{"prompt":"<p>Deux résistances de 150 Ω et 680 Ω sont en parallèle. Calculez la résistance équivalente, en Ω.</p>","unit":"Ω","answer":{"value":122.89156626506025,"rel":0.02},"display":"122,9 Ω","explanation":"<p>Req = R₁R₂/(R₁+R₂) = 122,9 Ω.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('circuits:ci-div','final-circuits','Diviseur de tension','numeric','[{"prompt":"<p>Un diviseur à vide est alimenté sous 12 V, avec R₁ = 1 000 Ω côté source et R₂ = 2 200 Ω côté masse. Calculez la tension aux bornes de R₂, en V.</p>","unit":"V","answer":{"value":8.25,"rel":0.02},"display":"8,25 V","explanation":"<p>U₂ = E·R₂/(R₁+R₂) = 8,25 V.</p>"},{"prompt":"<p>Un diviseur à vide est alimenté sous 9 V, avec R₁ = 470 Ω côté source et R₂ = 470 Ω côté masse. Calculez la tension aux bornes de R₂, en V.</p>","unit":"V","answer":{"value":4.5,"rel":0.02},"display":"4,5 V","explanation":"<p>U₂ = E·R₂/(R₁+R₂) = 4,5 V.</p>"},{"prompt":"<p>Un diviseur à vide est alimenté sous 5 V, avec R₁ = 3 300 Ω côté source et R₂ = 1 000 Ω côté masse. Calculez la tension aux bornes de R₂, en V.</p>","unit":"V","answer":{"value":1.1627906976744187,"rel":0.02},"display":"1,163 V","explanation":"<p>U₂ = E·R₂/(R₁+R₂) = 1,163 V.</p>"},{"prompt":"<p>Un diviseur à vide est alimenté sous 24 V, avec R₁ = 10 000 Ω côté source et R₂ = 4 700 Ω côté masse. Calculez la tension aux bornes de R₂, en V.</p>","unit":"V","answer":{"value":7.673469387755102,"rel":0.02},"display":"7,673 V","explanation":"<p>U₂ = E·R₂/(R₁+R₂) = 7,673 V.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('circuits:ci-pow','final-circuits','Puissance','numeric','[{"prompt":"<p>Une résistance de 100 Ω est parcourue par 50 mA. Calculez la puissance dissipée, <strong>en mW</strong>.</p>","unit":"mW","answer":{"value":250,"rel":0.02},"display":"250 mW","explanation":"<p>P = R·I² = 250 mW.</p>"},{"prompt":"<p>Une résistance de 470 Ω est parcourue par 20 mA. Calculez la puissance dissipée, <strong>en mW</strong>.</p>","unit":"mW","answer":{"value":188,"rel":0.02},"display":"188 mW","explanation":"<p>P = R·I² = 188 mW.</p>"},{"prompt":"<p>Une résistance de 220 Ω est parcourue par 100 mA. Calculez la puissance dissipée, <strong>en mW</strong>.</p>","unit":"mW","answer":{"value":2200,"rel":0.02},"display":"2 200 mW","explanation":"<p>P = R·I² = 2 200 mW.</p>"},{"prompt":"<p>Une résistance de 1 000 Ω est parcourue par 10 mA. Calculez la puissance dissipée, <strong>en mW</strong>.</p>","unit":"mW","answer":{"value":100,"rel":0.02},"display":"100 mW","explanation":"<p>P = R·I² = 100 mW.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('circuits:ci-tau','final-circuits','Circuit RC','numeric','[{"prompt":"<p>Un circuit RC comporte R = 1 000 Ω et C = 100 µF. Calculez sa constante de temps, <strong>en ms</strong>.</p>","unit":"ms","answer":{"value":99.99999999999999,"rel":0.02},"display":"100 ms","explanation":"<p>τ = R·C = 100 ms. Le condensateur atteint environ 63 % de la tension finale après τ.</p>"},{"prompt":"<p>Un circuit RC comporte R = 4 700 Ω et C = 10 µF. Calculez sa constante de temps, <strong>en ms</strong>.</p>","unit":"ms","answer":{"value":46.99999999999999,"rel":0.02},"display":"47 ms","explanation":"<p>τ = R·C = 47 ms. Le condensateur atteint environ 63 % de la tension finale après τ.</p>"},{"prompt":"<p>Un circuit RC comporte R = 10 000 Ω et C = 47 µF. Calculez sa constante de temps, <strong>en ms</strong>.</p>","unit":"ms","answer":{"value":470,"rel":0.02},"display":"470 ms","explanation":"<p>τ = R·C = 470 ms. Le condensateur atteint environ 63 % de la tension finale après τ.</p>"},{"prompt":"<p>Un circuit RC comporte R = 2 200 Ω et C = 220 µF. Calculez sa constante de temps, <strong>en ms</strong>.</p>","unit":"ms","answer":{"value":483.99999999999994,"rel":0.02},"display":"484 ms","explanation":"<p>τ = R·C = 484 ms. Le condensateur atteint environ 63 % de la tension finale après τ.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('circuits:ci-depannage','final-circuits','Dépannage','qcm','[{"prompt":"<p>Scénario de dépannage : dans un diviseur alimenté en 12 V, vous mesurez 12 V au point milieu, alors que le calcul prévoit 6 V. Que soupçonnez-vous d’abord ?</p>","options":[{"id":"a","label":"R₂ (côté masse) est coupée, aucun courant ne circule"},{"id":"b","label":"R₂ (côté masse) est en court-circuit"},{"id":"c","label":"L’alimentation délivre une tension trop faible"},{"id":"d","label":"R₁ a une valeur deux fois trop grande"}],"answer":{"id":"a"},"display":"R₂ (côté masse) est coupée, aucun courant ne circule","explanation":"<p>Sans courant, la chute dans R₁ est nulle : le point milieu monte à la tension de l’alimentation. Un court-circuit de R₂ donnerait 0 V.</p>"},{"prompt":"<p>Scénario de dépannage : dans un diviseur alimenté en 12 V, vous mesurez 12 V au point milieu, alors que le calcul prévoit 6 V. Que soupçonnez-vous d’abord ?</p>","options":[{"id":"a","label":"R₂ (côté masse) est en court-circuit"},{"id":"b","label":"R₂ (côté masse) est coupée, aucun courant ne circule"},{"id":"c","label":"L’alimentation délivre une tension trop faible"},{"id":"d","label":"R₁ a une valeur deux fois trop grande"}],"answer":{"id":"b"},"display":"R₂ (côté masse) est coupée, aucun courant ne circule","explanation":"<p>Sans courant, la chute dans R₁ est nulle : le point milieu monte à la tension de l’alimentation. Un court-circuit de R₂ donnerait 0 V.</p>"},{"prompt":"<p>Scénario de dépannage : dans un diviseur alimenté en 12 V, vous mesurez 12 V au point milieu, alors que le calcul prévoit 6 V. Que soupçonnez-vous d’abord ?</p>","options":[{"id":"a","label":"R₂ (côté masse) est en court-circuit"},{"id":"b","label":"L’alimentation délivre une tension trop faible"},{"id":"c","label":"R₂ (côté masse) est coupée, aucun courant ne circule"},{"id":"d","label":"R₁ a une valeur deux fois trop grande"}],"answer":{"id":"c"},"display":"R₂ (côté masse) est coupée, aucun courant ne circule","explanation":"<p>Sans courant, la chute dans R₁ est nulle : le point milieu monte à la tension de l’alimentation. Un court-circuit de R₂ donnerait 0 V.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into public.assessments (id,title,description,kind,competency,question_count,pass_percent,duration_seconds,max_attempts,cooldown_minutes,prerequisites,grants,status) values ('final-ac','Évaluation : Courant alternatif et circuits RLC','Évaluation de fin de module, corrigée par le serveur.','course_final','ac',5,70,1200,null,30,array['circuits']::text[],array[]::text[],'published') on conflict (id) do update set title=excluded.title, description=excluded.description, prerequisites=excluded.prerequisites, grants=excluded.grants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('ac:ac-eff','final-ac','Valeur efficace','numeric','[{"prompt":"<p>Une sinusoïde a une valeur efficace de 230 V. Calculez son amplitude, en V.</p>","unit":"V","answer":{"value":325.2691193458119,"rel":0.02},"display":"325,3 V","explanation":"<p>V<sub>p</sub> = V<sub>eff</sub> × √2.</p>"},{"prompt":"<p>Une sinusoïde a une valeur efficace de 120 V. Calculez son amplitude, en V.</p>","unit":"V","answer":{"value":169.7056274847714,"rel":0.02},"display":"169,7 V","explanation":"<p>V<sub>p</sub> = V<sub>eff</sub> × √2.</p>"},{"prompt":"<p>Une sinusoïde a une valeur efficace de 12 V. Calculez son amplitude, en V.</p>","unit":"V","answer":{"value":16.970562748477143,"rel":0.02},"display":"16,97 V","explanation":"<p>V<sub>p</sub> = V<sub>eff</sub> × √2.</p>"},{"prompt":"<p>Une sinusoïde a une valeur efficace de 48 V. Calculez son amplitude, en V.</p>","unit":"V","answer":{"value":67.88225099390857,"rel":0.02},"display":"67,88 V","explanation":"<p>V<sub>p</sub> = V<sub>eff</sub> × √2.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('ac:ac-xc','final-ac','Réactances','numeric','[{"prompt":"<p>Calculez la réactance d’un condensateur de 10 µF à 50 Hz, en Ω.</p>","unit":"Ω","answer":{"value":318.30988618379064,"rel":0.02},"display":"318,3 Ω","explanation":"<p>X<sub>C</sub> = 1/(2πfC).</p>"},{"prompt":"<p>Calculez la réactance d’un condensateur de 1 µF à 1 000 Hz, en Ω.</p>","unit":"Ω","answer":{"value":159.15494309189535,"rel":0.02},"display":"159,2 Ω","explanation":"<p>X<sub>C</sub> = 1/(2πfC).</p>"},{"prompt":"<p>Calculez la réactance d’un condensateur de 100 µF à 60 Hz, en Ω.</p>","unit":"Ω","answer":{"value":26.525823848649225,"rel":0.02},"display":"26,53 Ω","explanation":"<p>X<sub>C</sub> = 1/(2πfC).</p>"},{"prompt":"<p>Calculez la réactance d’un condensateur de 0,1 µF à 10 000 Hz, en Ω.</p>","unit":"Ω","answer":{"value":159.15494309189532,"rel":0.02},"display":"159,2 Ω","explanation":"<p>X<sub>C</sub> = 1/(2πfC).</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('ac:ac-z','final-ac','Impédance','numeric','[{"prompt":"<p>RLC série : R = 100 Ω, L = 0,1 H, C = 10 µF, f = 200 Hz. Calculez |Z|, en Ω.</p>","unit":"Ω","answer":{"value":110.10876903947788,"rel":0.02},"display":"110,1 Ω","explanation":"<p>|Z| = √(R² + (X<sub>L</sub> − X<sub>C</sub>)²).</p>"},{"prompt":"<p>RLC série : R = 50 Ω, L = 0,2 H, C = 20 µF, f = 100 Hz. Calculez |Z|, en Ω.</p>","unit":"Ω","answer":{"value":67.99956631765444,"rel":0.02},"display":"68 Ω","explanation":"<p>|Z| = √(R² + (X<sub>L</sub> − X<sub>C</sub>)²).</p>"},{"prompt":"<p>RLC série : R = 220 Ω, L = 0,05 H, C = 1 µF, f = 1 000 Hz. Calculez |Z|, en Ω.</p>","unit":"Ω","answer":{"value":269.1214222641483,"rel":0.02},"display":"269,1 Ω","explanation":"<p>|Z| = √(R² + (X<sub>L</sub> − X<sub>C</sub>)²).</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('ac:ac-res','final-ac','Résonance','numeric','[{"prompt":"<p>Calculez la fréquence de résonance pour L = 1 mH et C = 100 nF, en kHz.</p>","unit":"kHz","answer":{"value":15.915494309189533,"rel":0.02},"display":"15,92 kHz","explanation":"<p>f₀ = 1/(2π√(LC)).</p>"},{"prompt":"<p>Calculez la fréquence de résonance pour L = 10 mH et C = 1 nF, en kHz.</p>","unit":"kHz","answer":{"value":50.329212104487034,"rel":0.02},"display":"50,33 kHz","explanation":"<p>f₀ = 1/(2π√(LC)).</p>"},{"prompt":"<p>Calculez la fréquence de résonance pour L = 100 mH et C = 10 nF, en kHz.</p>","unit":"kHz","answer":{"value":5.032921210448703,"rel":0.02},"display":"5,033 kHz","explanation":"<p>f₀ = 1/(2π√(LC)).</p>"},{"prompt":"<p>Calculez la fréquence de résonance pour L = 0,5 mH et C = 47 nF, en kHz.</p>","unit":"kHz","answer":{"value":32.831157950418,"rel":0.02},"display":"32,83 kHz","explanation":"<p>f₀ = 1/(2π√(LC)).</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('ac:ac-p','final-ac','Puissances','numeric','[{"prompt":"<p>Un appareil sous 230 V absorbe 2 A, avec cos φ = 0,8. Calculez la puissance active, en W.</p>","unit":"W","answer":{"value":368,"rel":0.02},"display":"368 W","explanation":"<p>P = V·I·cos φ.</p>"},{"prompt":"<p>Un appareil sous 220 V absorbe 5 A, avec cos φ = 0,9. Calculez la puissance active, en W.</p>","unit":"W","answer":{"value":990,"rel":0.02},"display":"990 W","explanation":"<p>P = V·I·cos φ.</p>"},{"prompt":"<p>Un appareil sous 120 V absorbe 3 A, avec cos φ = 0,7. Calculez la puissance active, en W.</p>","unit":"W","answer":{"value":251.99999999999997,"rel":0.02},"display":"252 W","explanation":"<p>P = V·I·cos φ.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('ac:ac-reson','final-ac','Résonance','qcm','[{"prompt":"<p>Dans un circuit RLC série à la résonance, le courant est :</p>","options":[{"id":"a","label":"maximal et en phase avec la tension"},{"id":"b","label":"nul"},{"id":"c","label":"minimal"},{"id":"d","label":"en quadrature avec la tension"}],"answer":{"id":"a"},"display":"maximal et en phase avec la tension","explanation":"<p>La réactance totale s’annule, donc Z = R.</p>"},{"prompt":"<p>Dans un circuit RLC série à la résonance, le courant est :</p>","options":[{"id":"a","label":"nul"},{"id":"b","label":"maximal et en phase avec la tension"},{"id":"c","label":"minimal"},{"id":"d","label":"en quadrature avec la tension"}],"answer":{"id":"b"},"display":"maximal et en phase avec la tension","explanation":"<p>La réactance totale s’annule, donc Z = R.</p>"},{"prompt":"<p>Dans un circuit RLC série à la résonance, le courant est :</p>","options":[{"id":"a","label":"nul"},{"id":"b","label":"minimal"},{"id":"c","label":"maximal et en phase avec la tension"},{"id":"d","label":"en quadrature avec la tension"}],"answer":{"id":"c"},"display":"maximal et en phase avec la tension","explanation":"<p>La réactance totale s’annule, donc Z = R.</p>"},{"prompt":"<p>Dans un circuit RLC série à la résonance, le courant est :</p>","options":[{"id":"a","label":"nul"},{"id":"b","label":"minimal"},{"id":"c","label":"en quadrature avec la tension"},{"id":"d","label":"maximal et en phase avec la tension"}],"answer":{"id":"d"},"display":"maximal et en phase avec la tension","explanation":"<p>La réactance totale s’annule, donc Z = R.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into public.assessments (id,title,description,kind,competency,question_count,pass_percent,duration_seconds,max_attempts,cooldown_minutes,prerequisites,grants,status) values ('final-analyse','Évaluation : Analyse des circuits','Évaluation de fin de module, corrigée par le serveur.','course_final','analyse',5,70,1200,null,30,array['circuits']::text[],array[]::text[],'published') on conflict (id) do update set title=excluded.title, description=excluded.description, prerequisites=excluded.prerequisites, grants=excluded.grants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('analyse:an-th','final-analyse','Thévenin','numeric','[{"prompt":"<p>E₁ = 24 V, E₂ remplacée par un fil, R₁ = 1 000 Ω, R₂ = 1 000 Ω, R₃ = 2 000 Ω. Calculez V<sub>th</sub> au point A, en V.</p>","unit":"V","answer":{"value":9.6,"rel":0.02},"display":"9,6 V","explanation":"<p>V<sub>th</sub> = (E₁/R₁)/G avec G = 1/R₁ + 1/R₂ + 1/R₃.</p>"},{"prompt":"<p>E₁ = 12 V, E₂ remplacée par un fil, R₁ = 470 Ω, R₂ = 1 000 Ω, R₃ = 2 200 Ω. Calculez V<sub>th</sub> au point A, en V.</p>","unit":"V","answer":{"value":7.1274298056155505,"rel":0.02},"display":"7,127 V","explanation":"<p>V<sub>th</sub> = (E₁/R₁)/G avec G = 1/R₁ + 1/R₂ + 1/R₃.</p>"},{"prompt":"<p>E₁ = 9 V, E₂ remplacée par un fil, R₁ = 220 Ω, R₂ = 330 Ω, R₃ = 1 000 Ω. Calculez V<sub>th</sub> au point A, en V.</p>","unit":"V","answer":{"value":4.770318021201413,"rel":0.02},"display":"4,77 V","explanation":"<p>V<sub>th</sub> = (E₁/R₁)/G avec G = 1/R₁ + 1/R₂ + 1/R₃.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('analyse:an-rth','final-analyse','Thévenin','numeric','[{"prompt":"<p>Calculez R<sub>th</sub> de trois résistances en parallèle : 1 000 Ω, 1 000 Ω, 2 000 Ω.</p>","unit":"Ω","answer":{"value":400,"rel":0.02},"display":"400 Ω","explanation":"<p>R<sub>th</sub> = 1/(1/R₁ + 1/R₂ + 1/R₃).</p>"},{"prompt":"<p>Calculez R<sub>th</sub> de trois résistances en parallèle : 470 Ω, 1 000 Ω, 2 200 Ω.</p>","unit":"Ω","answer":{"value":279.1576673866091,"rel":0.02},"display":"279,2 Ω","explanation":"<p>R<sub>th</sub> = 1/(1/R₁ + 1/R₂ + 1/R₃).</p>"},{"prompt":"<p>Calculez R<sub>th</sub> de trois résistances en parallèle : 100 Ω, 200 Ω, 300 Ω.</p>","unit":"Ω","answer":{"value":54.54545454545455,"rel":0.02},"display":"54,55 Ω","explanation":"<p>R<sub>th</sub> = 1/(1/R₁ + 1/R₂ + 1/R₃).</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('analyse:an-norton','final-analyse','Norton','numeric','[{"prompt":"<p>V<sub>th</sub> = 9 V et R<sub>th</sub> = 450 Ω. Calculez I<sub>N</sub>, en mA.</p>","unit":"mA","answer":{"value":20,"rel":0.02},"display":"20 mA","explanation":"<p>I<sub>N</sub> = V<sub>th</sub>/R<sub>th</sub>.</p>"},{"prompt":"<p>V<sub>th</sub> = 12 V et R<sub>th</sub> = 60 Ω. Calculez I<sub>N</sub>, en mA.</p>","unit":"mA","answer":{"value":200,"rel":0.02},"display":"200 mA","explanation":"<p>I<sub>N</sub> = V<sub>th</sub>/R<sub>th</sub>.</p>"},{"prompt":"<p>V<sub>th</sub> = 5 V et R<sub>th</sub> = 250 Ω. Calculez I<sub>N</sub>, en mA.</p>","unit":"mA","answer":{"value":20,"rel":0.02},"display":"20 mA","explanation":"<p>I<sub>N</sub> = V<sub>th</sub>/R<sub>th</sub>.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('analyse:an-pmax','final-analyse','Transfert de puissance','numeric','[{"prompt":"<p>V<sub>th</sub> = 12 V, R<sub>th</sub> = 8 Ω. Calculez la puissance maximale disponible, en W.</p>","unit":"W","answer":{"value":4.5,"rel":0.02},"display":"4,5 W","explanation":"<p>P<sub>max</sub> = V²/(4R).</p>"},{"prompt":"<p>V<sub>th</sub> = 10 V, R<sub>th</sub> = 100 Ω. Calculez la puissance maximale disponible, en W.</p>","unit":"W","answer":{"value":0.25,"rel":0.02},"display":"0,25 W","explanation":"<p>P<sub>max</sub> = V²/(4R).</p>"},{"prompt":"<p>V<sub>th</sub> = 24 V, R<sub>th</sub> = 50 Ω. Calculez la puissance maximale disponible, en W.</p>","unit":"W","answer":{"value":2.88,"rel":0.02},"display":"2,88 W","explanation":"<p>P<sub>max</sub> = V²/(4R).</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('analyse:an-eta','final-analyse','Transfert de puissance','numeric','[{"prompt":"<p>R<sub>th</sub> = 10 Ω et R<sub>L</sub> = 90 Ω. Calculez le rendement, en %.</p>","unit":"%","answer":{"value":90,"rel":0.02},"display":"90 %","explanation":"<p>η = R<sub>L</sub>/(R<sub>L</sub> + R<sub>th</sub>).</p>"},{"prompt":"<p>R<sub>th</sub> = 50 Ω et R<sub>L</sub> = 50 Ω. Calculez le rendement, en %.</p>","unit":"%","answer":{"value":50,"rel":0.02},"display":"50 %","explanation":"<p>η = R<sub>L</sub>/(R<sub>L</sub> + R<sub>th</sub>).</p>"},{"prompt":"<p>R<sub>th</sub> = 25 Ω et R<sub>L</sub> = 75 Ω. Calculez le rendement, en %.</p>","unit":"%","answer":{"value":75,"rel":0.02},"display":"75 %","explanation":"<p>η = R<sub>L</sub>/(R<sub>L</sub> + R<sub>th</sub>).</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('analyse:an-off','final-analyse','Thévenin','qcm','[{"prompt":"<p>Pour calculer R<sub>th</sub>, une source de courant idéale est remplacée par :</p>","options":[{"id":"a","label":"un circuit ouvert"},{"id":"b","label":"un court-circuit"},{"id":"c","label":"une résistance de 1 Ω"},{"id":"d","label":"une source de tension"}],"answer":{"id":"a"},"display":"un circuit ouvert","explanation":"<p>Éteinte, elle impose un courant nul.</p>"},{"prompt":"<p>Pour calculer R<sub>th</sub>, une source de courant idéale est remplacée par :</p>","options":[{"id":"a","label":"un court-circuit"},{"id":"b","label":"un circuit ouvert"},{"id":"c","label":"une résistance de 1 Ω"},{"id":"d","label":"une source de tension"}],"answer":{"id":"b"},"display":"un circuit ouvert","explanation":"<p>Éteinte, elle impose un courant nul.</p>"},{"prompt":"<p>Pour calculer R<sub>th</sub>, une source de courant idéale est remplacée par :</p>","options":[{"id":"a","label":"un court-circuit"},{"id":"b","label":"une résistance de 1 Ω"},{"id":"c","label":"un circuit ouvert"},{"id":"d","label":"une source de tension"}],"answer":{"id":"c"},"display":"un circuit ouvert","explanation":"<p>Éteinte, elle impose un courant nul.</p>"},{"prompt":"<p>Pour calculer R<sub>th</sub>, une source de courant idéale est remplacée par :</p>","options":[{"id":"a","label":"un court-circuit"},{"id":"b","label":"une résistance de 1 Ω"},{"id":"c","label":"une source de tension"},{"id":"d","label":"un circuit ouvert"}],"answer":{"id":"d"},"display":"un circuit ouvert","explanation":"<p>Éteinte, elle impose un courant nul.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into public.assessments (id,title,description,kind,competency,question_count,pass_percent,duration_seconds,max_attempts,cooldown_minutes,prerequisites,grants,status) values ('final-diodes','Évaluation : Diodes et alimentations','Évaluation de fin de module, corrigée par le serveur.','course_final','diodes',5,70,1200,null,30,array['circuits']::text[],array[]::text[],'published') on conflict (id) do update set title=excluded.title, description=excluded.description, prerequisites=excluded.prerequisites, grants=excluded.grants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('diodes:di-crete','final-diodes','Redressement','numeric','[{"prompt":"<p>Un secondaire délivre 9 V efficaces. Calculez la tension de crête, en V.</p>","unit":"V","answer":{"value":12.727922061357857,"rel":0.02},"display":"12,73 V","explanation":"<p>V<sub>p</sub> = V<sub>eff</sub> × √2.</p>"},{"prompt":"<p>Un secondaire délivre 12 V efficaces. Calculez la tension de crête, en V.</p>","unit":"V","answer":{"value":16.970562748477143,"rel":0.02},"display":"16,97 V","explanation":"<p>V<sub>p</sub> = V<sub>eff</sub> × √2.</p>"},{"prompt":"<p>Un secondaire délivre 24 V efficaces. Calculez la tension de crête, en V.</p>","unit":"V","answer":{"value":33.941125496954285,"rel":0.02},"display":"33,94 V","explanation":"<p>V<sub>p</sub> = V<sub>eff</sub> × √2.</p>"},{"prompt":"<p>Un secondaire délivre 6 V efficaces. Calculez la tension de crête, en V.</p>","unit":"V","answer":{"value":8.485281374238571,"rel":0.02},"display":"8,485 V","explanation":"<p>V<sub>p</sub> = V<sub>eff</sub> × √2.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('diodes:di-moy','final-diodes','Redressement','numeric','[{"prompt":"<p>Redressement double alternance idéal, crête 10 V, sans condensateur. Calculez la tension moyenne, en V.</p>","unit":"V","answer":{"value":6.366197723675814,"rel":0.02},"display":"6,366 V","explanation":"<p>V<sub>moy</sub> = 2V<sub>p</sub>/π.</p>"},{"prompt":"<p>Redressement double alternance idéal, crête 17 V, sans condensateur. Calculez la tension moyenne, en V.</p>","unit":"V","answer":{"value":10.822536130248883,"rel":0.02},"display":"10,82 V","explanation":"<p>V<sub>moy</sub> = 2V<sub>p</sub>/π.</p>"},{"prompt":"<p>Redressement double alternance idéal, crête 34 V, sans condensateur. Calculez la tension moyenne, en V.</p>","unit":"V","answer":{"value":21.645072260497766,"rel":0.02},"display":"21,65 V","explanation":"<p>V<sub>moy</sub> = 2V<sub>p</sub>/π.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('diodes:di-c','final-diodes','Filtrage','numeric','[{"prompt":"<p>Pont à 50 Hz, 1 A de charge, 2 V d’ondulation admis. Calculez C minimal, en µF.</p>","unit":"µF","answer":{"value":5000,"rel":0.03},"display":"5 000 µF","explanation":"<p>C ≥ I/(2f·ΔV).</p>"},{"prompt":"<p>Pont à 50 Hz, 0,5 A de charge, 1 V d’ondulation admis. Calculez C minimal, en µF.</p>","unit":"µF","answer":{"value":5000,"rel":0.03},"display":"5 000 µF","explanation":"<p>C ≥ I/(2f·ΔV).</p>"},{"prompt":"<p>Pont à 50 Hz, 2 A de charge, 2,5 V d’ondulation admis. Calculez C minimal, en µF.</p>","unit":"µF","answer":{"value":8000,"rel":0.03},"display":"8 000 µF","explanation":"<p>C ≥ I/(2f·ΔV).</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('diodes:di-z','final-diodes','Stabilisation','numeric','[{"prompt":"<p>Entrée 12 V, R<sub>s</sub> = 100 Ω, V<sub>Z</sub> = 5,1 V, charge 470 Ω. Calculez I<sub>Z</sub>, en mA.</p>","unit":"mA","answer":{"value":58.14893617021277,"rel":0.03},"display":"58,15 mA","explanation":"<p>I<sub>Z</sub> = (V<sub>e</sub> − V<sub>Z</sub>)/R<sub>s</sub> − V<sub>Z</sub>/R<sub>L</sub>.</p>"},{"prompt":"<p>Entrée 15 V, R<sub>s</sub> = 220 Ω, V<sub>Z</sub> = 5,1 V, charge 1 000 Ω. Calculez I<sub>Z</sub>, en mA.</p>","unit":"mA","answer":{"value":39.9,"rel":0.03},"display":"39,9 mA","explanation":"<p>I<sub>Z</sub> = (V<sub>e</sub> − V<sub>Z</sub>)/R<sub>s</sub> − V<sub>Z</sub>/R<sub>L</sub>.</p>"},{"prompt":"<p>Entrée 9 V, R<sub>s</sub> = 68 Ω, V<sub>Z</sub> = 5,1 V, charge 330 Ω. Calculez I<sub>Z</sub>, en mA.</p>","unit":"mA","answer":{"value":41.898395721925134,"rel":0.03},"display":"41,9 mA","explanation":"<p>I<sub>Z</sub> = (V<sub>e</sub> − V<sub>Z</sub>)/R<sub>s</sub> − V<sub>Z</sub>/R<sub>L</sub>.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('diodes:di-reg','final-diodes','Stabilisation','numeric','[{"prompt":"<p>Un régulateur 5 V reçoit 12 V et débite 0,5 A. Calculez la puissance dissipée, en W.</p>","unit":"W","answer":{"value":3.5,"rel":0.02},"display":"3,5 W","explanation":"<p>P = (V<sub>e</sub> − V<sub>s</sub>) × I.</p>"},{"prompt":"<p>Un régulateur 5 V reçoit 9 V et débite 1 A. Calculez la puissance dissipée, en W.</p>","unit":"W","answer":{"value":4,"rel":0.02},"display":"4 W","explanation":"<p>P = (V<sub>e</sub> − V<sub>s</sub>) × I.</p>"},{"prompt":"<p>Un régulateur 5 V reçoit 15 V et débite 0,2 A. Calculez la puissance dissipée, en W.</p>","unit":"W","answer":{"value":2,"rel":0.02},"display":"2 W","explanation":"<p>P = (V<sub>e</sub> − V<sub>s</sub>) × I.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('diodes:di-cond','final-diodes','Jonction PN','qcm','[{"prompt":"<p>Une diode au silicium en conduction directe présente typiquement une chute de :</p>","options":[{"id":"a","label":"environ 0,6 à 1 V"},{"id":"b","label":"exactement 0 V"},{"id":"c","label":"environ 5 V"},{"id":"d","label":"la tension d’alimentation"}],"answer":{"id":"a"},"display":"environ 0,6 à 1 V","explanation":"<p>La chute dépend du courant, comme l’indiquent les fiches techniques.</p>"},{"prompt":"<p>Une diode au silicium en conduction directe présente typiquement une chute de :</p>","options":[{"id":"a","label":"exactement 0 V"},{"id":"b","label":"environ 0,6 à 1 V"},{"id":"c","label":"environ 5 V"},{"id":"d","label":"la tension d’alimentation"}],"answer":{"id":"b"},"display":"environ 0,6 à 1 V","explanation":"<p>La chute dépend du courant, comme l’indiquent les fiches techniques.</p>"},{"prompt":"<p>Une diode au silicium en conduction directe présente typiquement une chute de :</p>","options":[{"id":"a","label":"exactement 0 V"},{"id":"b","label":"environ 5 V"},{"id":"c","label":"environ 0,6 à 1 V"},{"id":"d","label":"la tension d’alimentation"}],"answer":{"id":"c"},"display":"environ 0,6 à 1 V","explanation":"<p>La chute dépend du courant, comme l’indiquent les fiches techniques.</p>"},{"prompt":"<p>Une diode au silicium en conduction directe présente typiquement une chute de :</p>","options":[{"id":"a","label":"exactement 0 V"},{"id":"b","label":"environ 5 V"},{"id":"c","label":"la tension d’alimentation"},{"id":"d","label":"environ 0,6 à 1 V"}],"answer":{"id":"d"},"display":"environ 0,6 à 1 V","explanation":"<p>La chute dépend du courant, comme l’indiquent les fiches techniques.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
