insert into private.questions (id,assessment_id,skill,kind,variants) values ('transistors:tr-ic','final-transistors','Bipolaire','numeric','[{"prompt":"<p>I<sub>B</sub> = 20 µA, β = 150, région active. Calculez I<sub>C</sub>, en mA.</p>","unit":"mA","answer":{"value":3,"rel":0.02},"display":"3 mA","explanation":"<p>I<sub>C</sub> = β I<sub>B</sub>.</p>"},{"prompt":"<p>I<sub>B</sub> = 10 µA, β = 200, région active. Calculez I<sub>C</sub>, en mA.</p>","unit":"mA","answer":{"value":2,"rel":0.02},"display":"2 mA","explanation":"<p>I<sub>C</sub> = β I<sub>B</sub>.</p>"},{"prompt":"<p>I<sub>B</sub> = 50 µA, β = 100, région active. Calculez I<sub>C</sub>, en mA.</p>","unit":"mA","answer":{"value":5,"rel":0.02},"display":"5 mA","explanation":"<p>I<sub>C</sub> = β I<sub>B</sub>.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('transistors:tr-vth','final-transistors','Polarisation','numeric','[{"prompt":"<p>V<sub>CC</sub> = 12 V, R₁ = 47 kΩ, R₂ = 10 kΩ. Calculez V<sub>th</sub> du pont, en V.</p>","unit":"V","answer":{"value":2.1052631578947367,"rel":0.02},"display":"2,105 V","explanation":"<p>V<sub>th</sub> = V<sub>CC</sub> R₂/(R₁ + R₂).</p>"},{"prompt":"<p>V<sub>CC</sub> = 15 V, R₁ = 68 kΩ, R₂ = 10 kΩ. Calculez V<sub>th</sub> du pont, en V.</p>","unit":"V","answer":{"value":1.9230769230769231,"rel":0.02},"display":"1,923 V","explanation":"<p>V<sub>th</sub> = V<sub>CC</sub> R₂/(R₁ + R₂).</p>"},{"prompt":"<p>V<sub>CC</sub> = 9 V, R₁ = 33 kΩ, R₂ = 10 kΩ. Calculez V<sub>th</sub> du pont, en V.</p>","unit":"V","answer":{"value":2.0930232558139537,"rel":0.02},"display":"2,093 V","explanation":"<p>V<sub>th</sub> = V<sub>CC</sub> R₂/(R₁ + R₂).</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('transistors:tr-gm','final-transistors','Amplification','numeric','[{"prompt":"<p>I<sub>C</sub> = 1 mA à 300 K. Calculez g<sub>m</sub>, en mS.</p>","unit":"mS","answer":{"value":38.68471953578336,"rel":0.03},"display":"38,68 mS","explanation":"<p>g<sub>m</sub> = I<sub>C</sub>/V<sub>T</sub>, V<sub>T</sub> ≈ 25,85 mV.</p>"},{"prompt":"<p>I<sub>C</sub> = 2 mA à 300 K. Calculez g<sub>m</sub>, en mS.</p>","unit":"mS","answer":{"value":77.36943907156672,"rel":0.03},"display":"77,37 mS","explanation":"<p>g<sub>m</sub> = I<sub>C</sub>/V<sub>T</sub>, V<sub>T</sub> ≈ 25,85 mV.</p>"},{"prompt":"<p>I<sub>C</sub> = 5 mA à 300 K. Calculez g<sub>m</sub>, en mS.</p>","unit":"mS","answer":{"value":193.42359767891682,"rel":0.03},"display":"193,4 mS","explanation":"<p>g<sub>m</sub> = I<sub>C</sub>/V<sub>T</sub>, V<sub>T</sub> ≈ 25,85 mV.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('transistors:tr-av','final-transistors','Amplification','numeric','[{"prompt":"<p>R<sub>C</sub> = 4 700 Ω, R<sub>E</sub> = 470 Ω non découplée. Calculez |A<sub>v</sub>| avec l’approximation usuelle.</p>","unit":"","answer":{"value":10,"rel":0.02},"display":"10","explanation":"<p>|A<sub>v</sub>| ≈ R<sub>C</sub>/R<sub>E</sub>.</p>"},{"prompt":"<p>R<sub>C</sub> = 2 200 Ω, R<sub>E</sub> = 220 Ω non découplée. Calculez |A<sub>v</sub>| avec l’approximation usuelle.</p>","unit":"","answer":{"value":10,"rel":0.02},"display":"10","explanation":"<p>|A<sub>v</sub>| ≈ R<sub>C</sub>/R<sub>E</sub>.</p>"},{"prompt":"<p>R<sub>C</sub> = 10 000 Ω, R<sub>E</sub> = 1 000 Ω non découplée. Calculez |A<sub>v</sub>| avec l’approximation usuelle.</p>","unit":"","answer":{"value":10,"rel":0.02},"display":"10","explanation":"<p>|A<sub>v</sub>| ≈ R<sub>C</sub>/R<sub>E</sub>.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('transistors:tr-mos','final-transistors','MOSFET','numeric','[{"prompt":"<p>k = 0,2 A/V², V<sub>th</sub> = 1,5 V, V<sub>GS</sub> = 3,5 V, en saturation, λ = 0. Calculez I<sub>D</sub>, en A.</p>","unit":"A","answer":{"value":0.4,"rel":0.02},"display":"0,4 A","explanation":"<p>I<sub>D</sub> = (k/2)(V<sub>GS</sub> − V<sub>th</sub>)².</p>"},{"prompt":"<p>k = 0,1 A/V², V<sub>th</sub> = 2 V, V<sub>GS</sub> = 4 V, en saturation, λ = 0. Calculez I<sub>D</sub>, en A.</p>","unit":"A","answer":{"value":0.2,"rel":0.02},"display":"0,2 A","explanation":"<p>I<sub>D</sub> = (k/2)(V<sub>GS</sub> − V<sub>th</sub>)².</p>"},{"prompt":"<p>k = 0,5 A/V², V<sub>th</sub> = 1 V, V<sub>GS</sub> = 2 V, en saturation, λ = 0. Calculez I<sub>D</sub>, en A.</p>","unit":"A","answer":{"value":0.25,"rel":0.02},"display":"0,25 A","explanation":"<p>I<sub>D</sub> = (k/2)(V<sub>GS</sub> − V<sub>th</sub>)².</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('transistors:tr-sat','final-transistors','Bipolaire','qcm','[{"prompt":"<p>En saturation, la tension V<sub>CE</sub> d’un NPN est :</p>","options":[{"id":"a","label":"faible, environ 0,2 V"},{"id":"b","label":"égale à V<sub>CC</sub>"},{"id":"c","label":"négative"},{"id":"d","label":"toujours égale à 5 V"}],"answer":{"id":"a"},"display":"faible, environ 0,2 V","explanation":"<p>Le transistor se comporte comme un interrupteur fermé.</p>"},{"prompt":"<p>En saturation, la tension V<sub>CE</sub> d’un NPN est :</p>","options":[{"id":"a","label":"égale à V<sub>CC</sub>"},{"id":"b","label":"faible, environ 0,2 V"},{"id":"c","label":"négative"},{"id":"d","label":"toujours égale à 5 V"}],"answer":{"id":"b"},"display":"faible, environ 0,2 V","explanation":"<p>Le transistor se comporte comme un interrupteur fermé.</p>"},{"prompt":"<p>En saturation, la tension V<sub>CE</sub> d’un NPN est :</p>","options":[{"id":"a","label":"égale à V<sub>CC</sub>"},{"id":"b","label":"négative"},{"id":"c","label":"faible, environ 0,2 V"},{"id":"d","label":"toujours égale à 5 V"}],"answer":{"id":"c"},"display":"faible, environ 0,2 V","explanation":"<p>Le transistor se comporte comme un interrupteur fermé.</p>"},{"prompt":"<p>En saturation, la tension V<sub>CE</sub> d’un NPN est :</p>","options":[{"id":"a","label":"égale à V<sub>CC</sub>"},{"id":"b","label":"négative"},{"id":"c","label":"toujours égale à 5 V"},{"id":"d","label":"faible, environ 0,2 V"}],"answer":{"id":"d"},"display":"faible, environ 0,2 V","explanation":"<p>Le transistor se comporte comme un interrupteur fermé.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
