insert into private.questions (id,assessment_id,skill,kind,variants) values ('aop:op-inv','final-aop','Montages','numeric','[{"prompt":"<p>Inverseur, R<sub>f</sub> = 47 kΩ et R<sub>g</sub> = 4,7 kΩ. Calculez le gain (avec son signe).</p>","unit":"","answer":{"value":-10,"rel":0.02},"display":"−10","explanation":"<p>G = −R<sub>f</sub>/R<sub>g</sub>.</p>"},{"prompt":"<p>Inverseur, R<sub>f</sub> = 100 kΩ et R<sub>g</sub> = 10 kΩ. Calculez le gain (avec son signe).</p>","unit":"","answer":{"value":-10,"rel":0.02},"display":"−10","explanation":"<p>G = −R<sub>f</sub>/R<sub>g</sub>.</p>"},{"prompt":"<p>Inverseur, R<sub>f</sub> = 22 kΩ et R<sub>g</sub> = 2,2 kΩ. Calculez le gain (avec son signe).</p>","unit":"","answer":{"value":-10,"rel":0.02},"display":"−10","explanation":"<p>G = −R<sub>f</sub>/R<sub>g</sub>.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('aop:op-non','final-aop','Montages','numeric','[{"prompt":"<p>Non inverseur, R<sub>f</sub> = 90 kΩ et R<sub>g</sub> = 10 kΩ. Calculez le gain.</p>","unit":"","answer":{"value":10,"rel":0.02},"display":"10","explanation":"<p>G = 1 + R<sub>f</sub>/R<sub>g</sub>.</p>"},{"prompt":"<p>Non inverseur, R<sub>f</sub> = 47 kΩ et R<sub>g</sub> = 10 kΩ. Calculez le gain.</p>","unit":"","answer":{"value":5.7,"rel":0.02},"display":"5,7","explanation":"<p>G = 1 + R<sub>f</sub>/R<sub>g</sub>.</p>"},{"prompt":"<p>Non inverseur, R<sub>f</sub> = 22 kΩ et R<sub>g</sub> = 2 kΩ. Calculez le gain.</p>","unit":"","answer":{"value":12,"rel":0.02},"display":"12","explanation":"<p>G = 1 + R<sub>f</sub>/R<sub>g</sub>.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('aop:op-bw','final-aop','Limites','numeric','[{"prompt":"<p>GBW = 1,5 MHz, gain de bruit 100. Calculez la bande passante, en kHz.</p>","unit":"kHz","answer":{"value":15,"rel":0.02},"display":"15 kHz","explanation":"<p>f<sub>c</sub> ≈ GBW/gain.</p>"},{"prompt":"<p>GBW = 10 MHz, gain de bruit 50. Calculez la bande passante, en kHz.</p>","unit":"kHz","answer":{"value":200,"rel":0.02},"display":"200 kHz","explanation":"<p>f<sub>c</sub> ≈ GBW/gain.</p>"},{"prompt":"<p>GBW = 3 MHz, gain de bruit 20. Calculez la bande passante, en kHz.</p>","unit":"kHz","answer":{"value":150,"rel":0.02},"display":"150 kHz","explanation":"<p>f<sub>c</sub> ≈ GBW/gain.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('aop:op-sr','final-aop','Limites','numeric','[{"prompt":"<p>SR = 0,5 V/µs, sortie de 5 V d’amplitude. Calculez la fréquence maximale, en kHz.</p>","unit":"kHz","answer":{"value":15.915494309189535,"rel":0.02},"display":"15,92 kHz","explanation":"<p>f = SR/(2πV<sub>p</sub>).</p>"},{"prompt":"<p>SR = 0,5 V/µs, sortie de 10 V d’amplitude. Calculez la fréquence maximale, en kHz.</p>","unit":"kHz","answer":{"value":7.957747154594768,"rel":0.02},"display":"7,958 kHz","explanation":"<p>f = SR/(2πV<sub>p</sub>).</p>"},{"prompt":"<p>SR = 13 V/µs, sortie de 10 V d’amplitude. Calculez la fréquence maximale, en kHz.</p>","unit":"kHz","answer":{"value":206.90142601946394,"rel":0.02},"display":"206,9 kHz","explanation":"<p>f = SR/(2πV<sub>p</sub>).</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('aop:op-rc','final-aop','Filtres','numeric','[{"prompt":"<p>R = 1 600 Ω, C = 100 nF. Calculez la fréquence de coupure du premier ordre, en Hz.</p>","unit":"Hz","answer":{"value":994.7183943243458,"rel":0.02},"display":"994,7 Hz","explanation":"<p>f<sub>c</sub> = 1/(2πRC).</p>"},{"prompt":"<p>R = 10 000 Ω, C = 10 nF. Calculez la fréquence de coupure du premier ordre, en Hz.</p>","unit":"Hz","answer":{"value":1591.5494309189532,"rel":0.02},"display":"1 592 Hz","explanation":"<p>f<sub>c</sub> = 1/(2πRC).</p>"},{"prompt":"<p>R = 470 Ω, C = 1 000 nF. Calculez la fréquence de coupure du premier ordre, en Hz.</p>","unit":"Hz","answer":{"value":338.6275384933943,"rel":0.02},"display":"338,6 Hz","explanation":"<p>f<sub>c</sub> = 1/(2πRC).</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('aop:op-osc','final-aop','Oscillateurs','qcm','[{"prompt":"<p>Pour un oscillateur de Wien, le gain de l’amplificateur doit être :</p>","options":[{"id":"a","label":"égal à 3"},{"id":"b","label":"égal à 1"},{"id":"c","label":"nul"},{"id":"d","label":"égal à 10"}],"answer":{"id":"a"},"display":"égal à 3","explanation":"<p>Le réseau de Wien atténue par 3 à sa fréquence centrale.</p>"},{"prompt":"<p>Pour un oscillateur de Wien, le gain de l’amplificateur doit être :</p>","options":[{"id":"a","label":"égal à 1"},{"id":"b","label":"égal à 3"},{"id":"c","label":"nul"},{"id":"d","label":"égal à 10"}],"answer":{"id":"b"},"display":"égal à 3","explanation":"<p>Le réseau de Wien atténue par 3 à sa fréquence centrale.</p>"},{"prompt":"<p>Pour un oscillateur de Wien, le gain de l’amplificateur doit être :</p>","options":[{"id":"a","label":"égal à 1"},{"id":"b","label":"nul"},{"id":"c","label":"égal à 3"},{"id":"d","label":"égal à 10"}],"answer":{"id":"c"},"display":"égal à 3","explanation":"<p>Le réseau de Wien atténue par 3 à sa fréquence centrale.</p>"},{"prompt":"<p>Pour un oscillateur de Wien, le gain de l’amplificateur doit être :</p>","options":[{"id":"a","label":"égal à 1"},{"id":"b","label":"nul"},{"id":"c","label":"égal à 10"},{"id":"d","label":"égal à 3"}],"answer":{"id":"d"},"display":"égal à 3","explanation":"<p>Le réseau de Wien atténue par 3 à sa fréquence centrale.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
