insert into private.questions (id,assessment_id,skill,kind,variants) values ('logique:lo-nand','final-logique','Portes','qcm','[{"prompt":"<p>A = 1 et B = 0 : la sortie d’une porte NON-ET vaut :</p>","options":[{"id":"a","label":"1"},{"id":"b","label":"0"},{"id":"c","label":"indéfinie"},{"id":"d","label":"la moitié de V<sub>cc</sub>"}],"answer":{"id":"a"},"display":"1","explanation":"<p>La sortie ne vaut 0 que si toutes les entrées valent 1.</p>"},{"prompt":"<p>A = 1 et B = 0 : la sortie d’une porte NON-ET vaut :</p>","options":[{"id":"a","label":"0"},{"id":"b","label":"1"},{"id":"c","label":"indéfinie"},{"id":"d","label":"la moitié de V<sub>cc</sub>"}],"answer":{"id":"b"},"display":"1","explanation":"<p>La sortie ne vaut 0 que si toutes les entrées valent 1.</p>"},{"prompt":"<p>A = 1 et B = 0 : la sortie d’une porte NON-ET vaut :</p>","options":[{"id":"a","label":"0"},{"id":"b","label":"indéfinie"},{"id":"c","label":"1"},{"id":"d","label":"la moitié de V<sub>cc</sub>"}],"answer":{"id":"c"},"display":"1","explanation":"<p>La sortie ne vaut 0 que si toutes les entrées valent 1.</p>"},{"prompt":"<p>A = 1 et B = 0 : la sortie d’une porte NON-ET vaut :</p>","options":[{"id":"a","label":"0"},{"id":"b","label":"indéfinie"},{"id":"c","label":"la moitié de V<sub>cc</sub>"},{"id":"d","label":"1"}],"answer":{"id":"d"},"display":"1","explanation":"<p>La sortie ne vaut 0 que si toutes les entrées valent 1.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('logique:lo-dm','final-logique','Algèbre de Boole','qcm','[{"prompt":"<p>Le complément de A·B est :</p>","options":[{"id":"a","label":"Ā + B̄"},{"id":"b","label":"Ā · B̄"},{"id":"c","label":"A + B"},{"id":"d","label":"A · B̄"}],"answer":{"id":"a"},"display":"Ā + B̄","explanation":"<p>Loi de De Morgan.</p>"},{"prompt":"<p>Le complément de A·B est :</p>","options":[{"id":"a","label":"Ā · B̄"},{"id":"b","label":"Ā + B̄"},{"id":"c","label":"A + B"},{"id":"d","label":"A · B̄"}],"answer":{"id":"b"},"display":"Ā + B̄","explanation":"<p>Loi de De Morgan.</p>"},{"prompt":"<p>Le complément de A·B est :</p>","options":[{"id":"a","label":"Ā · B̄"},{"id":"b","label":"A + B"},{"id":"c","label":"Ā + B̄"},{"id":"d","label":"A · B̄"}],"answer":{"id":"c"},"display":"Ā + B̄","explanation":"<p>Loi de De Morgan.</p>"},{"prompt":"<p>Le complément de A·B est :</p>","options":[{"id":"a","label":"Ā · B̄"},{"id":"b","label":"A + B"},{"id":"c","label":"A · B̄"},{"id":"d","label":"Ā + B̄"}],"answer":{"id":"d"},"display":"Ā + B̄","explanation":"<p>Loi de De Morgan.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('logique:lo-add','final-logique','Combinatoire','numeric','[{"prompt":"<p>Additionnez 1011 et 110 en binaire. Donnez le résultat en décimal.</p>","unit":"","answer":{"value":17,"abs":0.1},"display":"17","explanation":"<p>La retenue se propage de bit en bit.</p>"},{"prompt":"<p>Additionnez 1001 et 111 en binaire. Donnez le résultat en décimal.</p>","unit":"","answer":{"value":16,"abs":0.1},"display":"16","explanation":"<p>La retenue se propage de bit en bit.</p>"},{"prompt":"<p>Additionnez 1111 et 1 en binaire. Donnez le résultat en décimal.</p>","unit":"","answer":{"value":16,"abs":0.1},"display":"16","explanation":"<p>La retenue se propage de bit en bit.</p>"},{"prompt":"<p>Additionnez 101 et 1000 en binaire. Donnez le résultat en décimal.</p>","unit":"","answer":{"value":13,"abs":0.1},"display":"13","explanation":"<p>La retenue se propage de bit en bit.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('logique:lo-div','final-logique','Séquentiel','numeric','[{"prompt":"<p>Une horloge de 8 MHz traverse 3 bascules en diviseur. Calculez la fréquence de sortie, en MHz.</p>","unit":"MHz","answer":{"value":1,"rel":0.02},"display":"1 MHz","explanation":"<p>Chaque bascule divise la fréquence par deux.</p>"},{"prompt":"<p>Une horloge de 16 MHz traverse 4 bascules en diviseur. Calculez la fréquence de sortie, en MHz.</p>","unit":"MHz","answer":{"value":1,"rel":0.02},"display":"1 MHz","explanation":"<p>Chaque bascule divise la fréquence par deux.</p>"},{"prompt":"<p>Une horloge de 32 MHz traverse 5 bascules en diviseur. Calculez la fréquence de sortie, en MHz.</p>","unit":"MHz","answer":{"value":1,"rel":0.02},"display":"1 MHz","explanation":"<p>Chaque bascule divise la fréquence par deux.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('logique:lo-dff','final-logique','Séquentiel','qcm','[{"prompt":"<p>Entre deux fronts montants, la sortie d’une bascule D :</p>","options":[{"id":"a","label":"conserve sa valeur"},{"id":"b","label":"suit D en permanence"},{"id":"c","label":"s’annule"},{"id":"d","label":"oscille"}],"answer":{"id":"a"},"display":"conserve sa valeur","explanation":"<p>La bascule ne capture D qu’au front d’horloge.</p>"},{"prompt":"<p>Entre deux fronts montants, la sortie d’une bascule D :</p>","options":[{"id":"a","label":"suit D en permanence"},{"id":"b","label":"conserve sa valeur"},{"id":"c","label":"s’annule"},{"id":"d","label":"oscille"}],"answer":{"id":"b"},"display":"conserve sa valeur","explanation":"<p>La bascule ne capture D qu’au front d’horloge.</p>"},{"prompt":"<p>Entre deux fronts montants, la sortie d’une bascule D :</p>","options":[{"id":"a","label":"suit D en permanence"},{"id":"b","label":"s’annule"},{"id":"c","label":"conserve sa valeur"},{"id":"d","label":"oscille"}],"answer":{"id":"c"},"display":"conserve sa valeur","explanation":"<p>La bascule ne capture D qu’au front d’horloge.</p>"},{"prompt":"<p>Entre deux fronts montants, la sortie d’une bascule D :</p>","options":[{"id":"a","label":"suit D en permanence"},{"id":"b","label":"s’annule"},{"id":"c","label":"oscille"},{"id":"d","label":"conserve sa valeur"}],"answer":{"id":"d"},"display":"conserve sa valeur","explanation":"<p>La bascule ne capture D qu’au front d’horloge.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
