insert into private.questions (id,assessment_id,skill,kind,variants) values ('can:ca-fs','final-can','Échantillonnage','numeric','[{"prompt":"<p>Un signal occupe jusqu’à 20 kHz. Calculez la fréquence minimale théorique d’échantillonnage, en kHz.</p>","unit":"kHz","answer":{"value":40,"rel":0.02},"display":"40 kHz","explanation":"<p>f<sub>e</sub> > 2B.</p>"},{"prompt":"<p>Un signal occupe jusqu’à 4 kHz. Calculez la fréquence minimale théorique d’échantillonnage, en kHz.</p>","unit":"kHz","answer":{"value":8,"rel":0.02},"display":"8 kHz","explanation":"<p>f<sub>e</sub> > 2B.</p>"},{"prompt":"<p>Un signal occupe jusqu’à 3,4 kHz. Calculez la fréquence minimale théorique d’échantillonnage, en kHz.</p>","unit":"kHz","answer":{"value":6.8,"rel":0.02},"display":"6,8 kHz","explanation":"<p>f<sub>e</sub> > 2B.</p>"},{"prompt":"<p>Un signal occupe jusqu’à 100 kHz. Calculez la fréquence minimale théorique d’échantillonnage, en kHz.</p>","unit":"kHz","answer":{"value":200,"rel":0.02},"display":"200 kHz","explanation":"<p>f<sub>e</sub> > 2B.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('can:ca-alias','final-can','Échantillonnage','numeric','[{"prompt":"<p>Une sinusoïde de 7 kHz est échantillonnée à 10 kHz. À quelle fréquence apparaît-elle, en kHz ?</p>","unit":"kHz","answer":{"value":3,"rel":0.02},"display":"3 kHz","explanation":"<p>f apparente = |f − k·f<sub>e</sub>|.</p>"},{"prompt":"<p>Une sinusoïde de 11 kHz est échantillonnée à 8 kHz. À quelle fréquence apparaît-elle, en kHz ?</p>","unit":"kHz","answer":{"value":3,"rel":0.02},"display":"3 kHz","explanation":"<p>f apparente = |f − k·f<sub>e</sub>|.</p>"},{"prompt":"<p>Une sinusoïde de 900 kHz est échantillonnée à 1 000 kHz. À quelle fréquence apparaît-elle, en kHz ?</p>","unit":"kHz","answer":{"value":100,"rel":0.02},"display":"100 kHz","explanation":"<p>f apparente = |f − k·f<sub>e</sub>|.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('can:ca-lsb','final-can','Quantification','numeric','[{"prompt":"<p>CAN 12 bits, référence 3,3 V. Calculez le pas, en mV.</p>","unit":"mV","answer":{"value":0.8056640625,"rel":0.02},"display":"0,8057 mV","explanation":"<p>q = V<sub>ref</sub>/2<sup>N</sup>.</p>"},{"prompt":"<p>CAN 10 bits, référence 5 V. Calculez le pas, en mV.</p>","unit":"mV","answer":{"value":4.8828125,"rel":0.02},"display":"4,883 mV","explanation":"<p>q = V<sub>ref</sub>/2<sup>N</sup>.</p>"},{"prompt":"<p>CAN 8 bits, référence 2,048 V. Calculez le pas, en mV.</p>","unit":"mV","answer":{"value":8,"rel":0.02},"display":"8 mV","explanation":"<p>q = V<sub>ref</sub>/2<sup>N</sup>.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('can:ca-snr','final-can','Quantification','numeric','[{"prompt":"<p>Calculez le SNR théorique d’un CAN 8 bits, en dB.</p>","unit":"dB","answer":{"value":49.919999999999995,"rel":0.01},"display":"49,92 dB","explanation":"<p>SNR ≈ 6,02N + 1,76 dB.</p>"},{"prompt":"<p>Calculez le SNR théorique d’un CAN 10 bits, en dB.</p>","unit":"dB","answer":{"value":61.959999999999994,"rel":0.01},"display":"61,96 dB","explanation":"<p>SNR ≈ 6,02N + 1,76 dB.</p>"},{"prompt":"<p>Calculez le SNR théorique d’un CAN 12 bits, en dB.</p>","unit":"dB","answer":{"value":74,"rel":0.01},"display":"74 dB","explanation":"<p>SNR ≈ 6,02N + 1,76 dB.</p>"},{"prompt":"<p>Calculez le SNR théorique d’un CAN 16 bits, en dB.</p>","unit":"dB","answer":{"value":98.08,"rel":0.01},"display":"98,08 dB","explanation":"<p>SNR ≈ 6,02N + 1,76 dB.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('can:ca-dac','final-can','CNA','numeric','[{"prompt":"<p>CNA 8 bits, V<sub>ref</sub> = 5 V, code 128. Calculez la sortie, en V.</p>","unit":"V","answer":{"value":2.5,"rel":0.02},"display":"2,5 V","explanation":"<p>V = V<sub>ref</sub>·C/2<sup>N</sup>.</p>"},{"prompt":"<p>CNA 8 bits, V<sub>ref</sub> = 2,56 V, code 200. Calculez la sortie, en V.</p>","unit":"V","answer":{"value":2,"rel":0.02},"display":"2 V","explanation":"<p>V = V<sub>ref</sub>·C/2<sup>N</sup>.</p>"},{"prompt":"<p>CNA 10 bits, V<sub>ref</sub> = 3,3 V, code 512. Calculez la sortie, en V.</p>","unit":"V","answer":{"value":1.65,"rel":0.02},"display":"1,65 V","explanation":"<p>V = V<sub>ref</sub>·C/2<sup>N</sup>.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('can:ca-aa','final-can','Échantillonnage','qcm','[{"prompt":"<p>Le filtre anti-repliement se place :</p>","options":[{"id":"a","label":"avant l’échantillonneur"},{"id":"b","label":"après le CNA uniquement"},{"id":"c","label":"dans le processeur"},{"id":"d","label":"sur la référence"}],"answer":{"id":"a"},"display":"avant l’échantillonneur","explanation":"<p>Une fois replié, un signal ne peut plus être corrigé.</p>"},{"prompt":"<p>Le filtre anti-repliement se place :</p>","options":[{"id":"a","label":"après le CNA uniquement"},{"id":"b","label":"avant l’échantillonneur"},{"id":"c","label":"dans le processeur"},{"id":"d","label":"sur la référence"}],"answer":{"id":"b"},"display":"avant l’échantillonneur","explanation":"<p>Une fois replié, un signal ne peut plus être corrigé.</p>"},{"prompt":"<p>Le filtre anti-repliement se place :</p>","options":[{"id":"a","label":"après le CNA uniquement"},{"id":"b","label":"dans le processeur"},{"id":"c","label":"avant l’échantillonneur"},{"id":"d","label":"sur la référence"}],"answer":{"id":"c"},"display":"avant l’échantillonneur","explanation":"<p>Une fois replié, un signal ne peut plus être corrigé.</p>"},{"prompt":"<p>Le filtre anti-repliement se place :</p>","options":[{"id":"a","label":"après le CNA uniquement"},{"id":"b","label":"dans le processeur"},{"id":"c","label":"sur la référence"},{"id":"d","label":"avant l’échantillonneur"}],"answer":{"id":"d"},"display":"avant l’échantillonneur","explanation":"<p>Une fois replié, un signal ne peut plus être corrigé.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
