insert into private.questions (id,assessment_id,skill,kind,variants) values ('mesures:me-inc','final-mesures','Multimètre','numeric','[{"prompt":"<p>Lecture 12 V, précision ±(0,5 % + 2 digits), résolution 0,01 V. Calculez l’incertitude, en V.</p>","unit":"V","answer":{"value":0.08,"rel":0.03},"display":"0,08 V","explanation":"<p>Δx = a % × lecture + b × résolution.</p>"},{"prompt":"<p>Lecture 5 V, précision ±(1 % + 2 digits), résolution 0,01 V. Calculez l’incertitude, en V.</p>","unit":"V","answer":{"value":0.07,"rel":0.03},"display":"0,07 V","explanation":"<p>Δx = a % × lecture + b × résolution.</p>"},{"prompt":"<p>Lecture 230 V, précision ±(1,2 % + 5 digits), résolution 0,1 V. Calculez l’incertitude, en V.</p>","unit":"V","answer":{"value":3.26,"rel":0.03},"display":"3,26 V","explanation":"<p>Δx = a % × lecture + b × résolution.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('mesures:me-f','final-mesures','Oscilloscope','numeric','[{"prompt":"<p>Une période occupe 5 carreaux à 100 µs/div. Calculez la fréquence, en kHz.</p>","unit":"kHz","answer":{"value":2,"rel":0.02},"display":"2 kHz","explanation":"<p>f = 1/(N<sub>div</sub> × s/div).</p>"},{"prompt":"<p>Une période occupe 4 carreaux à 200 µs/div. Calculez la fréquence, en kHz.</p>","unit":"kHz","answer":{"value":1.25,"rel":0.02},"display":"1,25 kHz","explanation":"<p>f = 1/(N<sub>div</sub> × s/div).</p>"},{"prompt":"<p>Une période occupe 8 carreaux à 50 µs/div. Calculez la fréquence, en kHz.</p>","unit":"kHz","answer":{"value":2.5,"rel":0.02},"display":"2,5 kHz","explanation":"<p>f = 1/(N<sub>div</sub> × s/div).</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('mesures:me-v','final-mesures','Oscilloscope','numeric','[{"prompt":"<p>Le signal couvre 6 carreaux à 0,5 V/div. Calculez V<sub>cc</sub>, en V.</p>","unit":"V","answer":{"value":3,"rel":0.02},"display":"3 V","explanation":"<p>V<sub>cc</sub> = carreaux × V/div.</p>"},{"prompt":"<p>Le signal couvre 4 carreaux à 2 V/div. Calculez V<sub>cc</sub>, en V.</p>","unit":"V","answer":{"value":8,"rel":0.02},"display":"8 V","explanation":"<p>V<sub>cc</sub> = carreaux × V/div.</p>"},{"prompt":"<p>Le signal couvre 5 carreaux à 1 V/div. Calculez V<sub>cc</sub>, en V.</p>","unit":"V","answer":{"value":5,"rel":0.02},"display":"5 V","explanation":"<p>V<sub>cc</sub> = carreaux × V/div.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('mesures:me-rms','final-mesures','Oscilloscope','numeric','[{"prompt":"<p>Sinusoïde d’amplitude 2,5 V. Calculez sa valeur efficace, en V.</p>","unit":"V","answer":{"value":1.7677669529663687,"rel":0.02},"display":"1,768 V","explanation":"<p>V<sub>eff</sub> = V<sub>p</sub>/√2.</p>"},{"prompt":"<p>Sinusoïde d’amplitude 5 V. Calculez sa valeur efficace, en V.</p>","unit":"V","answer":{"value":3.5355339059327373,"rel":0.02},"display":"3,536 V","explanation":"<p>V<sub>eff</sub> = V<sub>p</sub>/√2.</p>"},{"prompt":"<p>Sinusoïde d’amplitude 10 V. Calculez sa valeur efficace, en V.</p>","unit":"V","answer":{"value":7.071067811865475,"rel":0.02},"display":"7,071 V","explanation":"<p>V<sub>eff</sub> = V<sub>p</sub>/√2.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('mesures:me-load','final-mesures','Influence de l’instrument','numeric','[{"prompt":"<p>Source de résistance 1 MΩ, voltmètre de 10 MΩ. Calculez le rapport tension lue/tension réelle, en %.</p>","unit":"%","answer":{"value":90.9090909090909,"rel":0.02},"display":"90,91 %","explanation":"<p>Rapport = R<sub>m</sub>/(R<sub>s</sub> + R<sub>m</sub>).</p>"},{"prompt":"<p>Source de résistance 100 kΩ, voltmètre de 10 MΩ. Calculez le rapport tension lue/tension réelle, en %.</p>","unit":"%","answer":{"value":99.00990099009901,"rel":0.02},"display":"99,01 %","explanation":"<p>Rapport = R<sub>m</sub>/(R<sub>s</sub> + R<sub>m</sub>).</p>"},{"prompt":"<p>Source de résistance 1 MΩ, voltmètre de 1 MΩ. Calculez le rapport tension lue/tension réelle, en %.</p>","unit":"%","answer":{"value":50,"rel":0.02},"display":"50 %","explanation":"<p>Rapport = R<sub>m</sub>/(R<sub>s</sub> + R<sub>m</sub>).</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
