insert into private.questions (id,assessment_id,skill,kind,variants) values ('rf:rf-g','final-rf','Réflexion','numeric','[{"prompt":"<p>Charge de 100 Ω sur une ligne de 50 Ω. Calculez |Γ|.</p>","unit":"","answer":{"value":0.3333333333333333,"rel":0.02},"display":"0,3333","explanation":"<p>Γ = (Z<sub>L</sub> − Z₀)/(Z<sub>L</sub> + Z₀).</p>"},{"prompt":"<p>Charge de 75 Ω sur une ligne de 50 Ω. Calculez |Γ|.</p>","unit":"","answer":{"value":0.2,"rel":0.02},"display":"0,2","explanation":"<p>Γ = (Z<sub>L</sub> − Z₀)/(Z<sub>L</sub> + Z₀).</p>"},{"prompt":"<p>Charge de 25 Ω sur une ligne de 50 Ω. Calculez |Γ|.</p>","unit":"","answer":{"value":0.3333333333333333,"rel":0.02},"display":"0,3333","explanation":"<p>Γ = (Z<sub>L</sub> − Z₀)/(Z<sub>L</sub> + Z₀).</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('rf:rf-swr','final-rf','Réflexion','numeric','[{"prompt":"<p>Calculez le ROS pour |Γ| = 0,2.</p>","unit":"","answer":{"value":1.4999999999999998,"rel":0.02},"display":"1,5","explanation":"<p>ROS = (1 + |Γ|)/(1 − |Γ|).</p>"},{"prompt":"<p>Calculez le ROS pour |Γ| = 0,3333.</p>","unit":"","answer":{"value":1.9999999999999998,"rel":0.02},"display":"2","explanation":"<p>ROS = (1 + |Γ|)/(1 − |Γ|).</p>"},{"prompt":"<p>Calculez le ROS pour |Γ| = 0,5.</p>","unit":"","answer":{"value":3,"rel":0.02},"display":"3","explanation":"<p>ROS = (1 + |Γ|)/(1 − |Γ|).</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('rf:rf-rl','final-rf','Réflexion','numeric','[{"prompt":"<p>|Γ| = 0,1. Calculez l’affaiblissement de réflexion, en dB.</p>","unit":"dB","answer":{"value":19.999999999999996,"rel":0.02},"display":"20 dB","explanation":"<p>RL = −20 log₁₀|Γ|.</p>"},{"prompt":"<p>|Γ| = 0,5. Calculez l’affaiblissement de réflexion, en dB.</p>","unit":"dB","answer":{"value":6.020599913279623,"rel":0.02},"display":"6,021 dB","explanation":"<p>RL = −20 log₁₀|Γ|.</p>"},{"prompt":"<p>|Γ| = 0,05. Calculez l’affaiblissement de réflexion, en dB.</p>","unit":"dB","answer":{"value":26.02059991327962,"rel":0.02},"display":"26,02 dB","explanation":"<p>RL = −20 log₁₀|Γ|.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('rf:rf-qw','final-rf','Transformation','numeric','[{"prompt":"<p>Ligne quart d’onde de 75 Ω chargée par 50 Ω. Calculez Z<sub>in</sub>, en Ω.</p>","unit":"Ω","answer":{"value":112.5,"rel":0.02},"display":"112,5 Ω","explanation":"<p>Z<sub>in</sub> = Z₀²/Z<sub>L</sub>.</p>"},{"prompt":"<p>Ligne quart d’onde de 50 Ω chargée par 100 Ω. Calculez Z<sub>in</sub>, en Ω.</p>","unit":"Ω","answer":{"value":25,"rel":0.02},"display":"25 Ω","explanation":"<p>Z<sub>in</sub> = Z₀²/Z<sub>L</sub>.</p>"},{"prompt":"<p>Ligne quart d’onde de 70 Ω chargée par 35 Ω. Calculez Z<sub>in</sub>, en Ω.</p>","unit":"Ω","answer":{"value":140,"rel":0.02},"display":"140 Ω","explanation":"<p>Z<sub>in</sub> = Z₀²/Z<sub>L</sub>.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('rf:rf-l','final-rf','Adaptation','numeric','[{"prompt":"<p>Réseau en L adaptant 50 Ω à 200 Ω. Calculez Q.</p>","unit":"","answer":{"value":1.7320508075688772,"rel":0.02},"display":"1,732","explanation":"<p>Q = √(R<sub>h</sub>/R<sub>b</sub> − 1).</p>"},{"prompt":"<p>Réseau en L adaptant 50 Ω à 450 Ω. Calculez Q.</p>","unit":"","answer":{"value":2.8284271247461903,"rel":0.02},"display":"2,828","explanation":"<p>Q = √(R<sub>h</sub>/R<sub>b</sub> − 1).</p>"},{"prompt":"<p>Réseau en L adaptant 75 Ω à 300 Ω. Calculez Q.</p>","unit":"","answer":{"value":1.7320508075688772,"rel":0.02},"display":"1,732","explanation":"<p>Q = √(R<sub>h</sub>/R<sub>b</sub> − 1).</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
