insert into private.questions (id,assessment_id,skill,kind,variants) values ('iot-capteurs:ic-r','final-iot-capteurs','Capteurs','numeric','[{"prompt":"<p>CTN R₀ = 10 kΩ à 25 °C, B = 3950. Calculez R à 50 °C, en kΩ.</p>","unit":"kΩ","answer":{"value":3.5881825819290833,"rel":0.02},"display":"3,588 kΩ","explanation":"<p>R = R₀ exp(B(1/T − 1/T₀)), T en kelvins.</p>"},{"prompt":"<p>CTN R₀ = 10 kΩ à 25 °C, B = 3950. Calculez R à 0 °C, en kΩ.</p>","unit":"kΩ","answer":{"value":33.62060372143574,"rel":0.02},"display":"33,62 kΩ","explanation":"<p>R = R₀ exp(B(1/T − 1/T₀)), T en kelvins.</p>"},{"prompt":"<p>CTN R₀ = 10 kΩ à 25 °C, B = 3950. Calculez R à 80 °C, en kΩ.</p>","unit":"kΩ","answer":{"value":1.2703202348436204,"rel":0.02},"display":"1,27 kΩ","explanation":"<p>R = R₀ exp(B(1/T − 1/T₀)), T en kelvins.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('iot-capteurs:ic-v','final-iot-capteurs','Capteurs','numeric','[{"prompt":"<p>V<sub>cc</sub> = 5 V, R<sub>fixe</sub> = 10 kΩ, R<sub>CTN</sub> = 15 kΩ. Calculez V, en V.</p>","unit":"V","answer":{"value":3,"rel":0.02},"display":"3 V","explanation":"<p>V = V<sub>cc</sub> R<sub>CTN</sub>/(R<sub>fixe</sub> + R<sub>CTN</sub>).</p>"},{"prompt":"<p>V<sub>cc</sub> = 3,3 V, R<sub>fixe</sub> = 10 kΩ, R<sub>CTN</sub> = 10 kΩ. Calculez V, en V.</p>","unit":"V","answer":{"value":1.65,"rel":0.02},"display":"1,65 V","explanation":"<p>V = V<sub>cc</sub> R<sub>CTN</sub>/(R<sub>fixe</sub> + R<sub>CTN</sub>).</p>"},{"prompt":"<p>V<sub>cc</sub> = 5 V, R<sub>fixe</sub> = 22 kΩ, R<sub>CTN</sub> = 10 kΩ. Calculez V, en V.</p>","unit":"V","answer":{"value":1.5625,"rel":0.02},"display":"1,563 V","explanation":"<p>V = V<sub>cc</sub> R<sub>CTN</sub>/(R<sub>fixe</sub> + R<sub>CTN</sub>).</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
