insert into private.questions (id,assessment_id,skill,kind,variants) values ('iot-com:im-toa','final-iot-com','LoRa','numeric','[{"prompt":"<p>SF7, 125 kHz, CR 4/5, 20 octets, préambule 8, CRC activé, en-tête explicite. Calculez le temps d’antenne, en ms.</p>","unit":"ms","answer":{"value":56.57599999999999,"rel":0.03},"display":"56,58 ms","explanation":"<p>T = (n + 4,25)T<sub>s</sub> + n<sub>charge</sub>T<sub>s</sub>.</p>"},{"prompt":"<p>SF9, 125 kHz, CR 4/5, 20 octets, préambule 8, CRC activé, en-tête explicite. Calculez le temps d’antenne, en ms.</p>","unit":"ms","answer":{"value":185.344,"rel":0.03},"display":"185,3 ms","explanation":"<p>T = (n + 4,25)T<sub>s</sub> + n<sub>charge</sub>T<sub>s</sub>.</p>"},{"prompt":"<p>SF12, 125 kHz, CR 4/5, 12 octets, préambule 8, CRC activé, en-tête explicite. Calculez le temps d’antenne, en ms.</p>","unit":"ms","answer":{"value":1155.0720000000001,"rel":0.03},"display":"1 155 ms","explanation":"<p>T = (n + 4,25)T<sub>s</sub> + n<sub>charge</sub>T<sub>s</sub>.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('iot-com:im-s','final-iot-com','Portée','numeric','[{"prompt":"<p>SF7, 125 kHz, NF = 6 dB. La limite de SNR est −7,5 dB. Calculez la sensibilité, en dBm.</p>","unit":"dBm","answer":{"value":-124.53089986991944,"abs":0.3},"display":"−124,5 dBm","explanation":"<p>S = −174 + 10 log₁₀ BW + NF + SNR.</p>"},{"prompt":"<p>SF10, 125 kHz, NF = 6 dB. La limite de SNR est −15 dB. Calculez la sensibilité, en dBm.</p>","unit":"dBm","answer":{"value":-132.03089986991944,"abs":0.3},"display":"−132 dBm","explanation":"<p>S = −174 + 10 log₁₀ BW + NF + SNR.</p>"},{"prompt":"<p>SF12, 125 kHz, NF = 6 dB. La limite de SNR est −20 dB. Calculez la sensibilité, en dBm.</p>","unit":"dBm","answer":{"value":-137.03089986991944,"abs":0.3},"display":"−137 dBm","explanation":"<p>S = −174 + 10 log₁₀ BW + NF + SNR.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
