insert into private.questions (id,assessment_id,skill,kind,variants) values ('placement-mobiles:si-per','placement-mobiles','Période et fréquence','numeric','[{"prompt":"<p>Un signal sinusoïdal a une fréquence de 50 Hz. Calculez sa période, <strong>en ms</strong>.</p>","unit":"ms","answer":{"value":20,"rel":0.02},"display":"20 ms","explanation":"<p>T = 1/f = 20 ms.</p>"},{"prompt":"<p>Un signal sinusoïdal a une fréquence de 250 Hz. Calculez sa période, <strong>en ms</strong>.</p>","unit":"ms","answer":{"value":4,"rel":0.02},"display":"4 ms","explanation":"<p>T = 1/f = 4 ms.</p>"},{"prompt":"<p>Un signal sinusoïdal a une fréquence de 400 Hz. Calculez sa période, <strong>en ms</strong>.</p>","unit":"ms","answer":{"value":2.5,"rel":0.02},"display":"2,5 ms","explanation":"<p>T = 1/f = 2,5 ms.</p>"},{"prompt":"<p>Un signal sinusoïdal a une fréquence de 1 000 Hz. Calculez sa période, <strong>en ms</strong>.</p>","unit":"ms","answer":{"value":1,"rel":0.02},"display":"1 ms","explanation":"<p>T = 1/f = 1 ms.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('placement-mobiles:si-freq','placement-mobiles','Période et fréquence','numeric','[{"prompt":"<p>Sur l’oscilloscope, un cycle dure 2,5 ms. Calculez la fréquence, en Hz.</p>","unit":"Hz","answer":{"value":400,"rel":0.02},"display":"400 Hz","explanation":"<p>f = 1/T = 400 Hz.</p>"},{"prompt":"<p>Sur l’oscilloscope, un cycle dure 4 ms. Calculez la fréquence, en Hz.</p>","unit":"Hz","answer":{"value":250,"rel":0.02},"display":"250 Hz","explanation":"<p>f = 1/T = 250 Hz.</p>"},{"prompt":"<p>Sur l’oscilloscope, un cycle dure 8 ms. Calculez la fréquence, en Hz.</p>","unit":"Hz","answer":{"value":125,"rel":0.02},"display":"125 Hz","explanation":"<p>f = 1/T = 125 Hz.</p>"},{"prompt":"<p>Sur l’oscilloscope, un cycle dure 20 ms. Calculez la fréquence, en Hz.</p>","unit":"Hz","answer":{"value":50,"rel":0.02},"display":"50 Hz","explanation":"<p>f = 1/T = 50 Hz.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('placement-mobiles:si-puls','placement-mobiles','Pulsation','numeric','[{"prompt":"<p>Calculez la pulsation ω d’un signal de 50 Hz, en rad/s.</p>","unit":"rad/s","answer":{"value":314.1592653589793,"rel":0.02},"display":"314,2 rad/s","explanation":"<p>ω = 2πf = 314,2 rad/s.</p>"},{"prompt":"<p>Calculez la pulsation ω d’un signal de 100 Hz, en rad/s.</p>","unit":"rad/s","answer":{"value":628.3185307179587,"rel":0.02},"display":"628,3 rad/s","explanation":"<p>ω = 2πf = 628,3 rad/s.</p>"},{"prompt":"<p>Calculez la pulsation ω d’un signal de 159 Hz, en rad/s.</p>","unit":"rad/s","answer":{"value":999.0264638415542,"rel":0.02},"display":"999 rad/s","explanation":"<p>ω = 2πf = 999 rad/s.</p>"},{"prompt":"<p>Calculez la pulsation ω d’un signal de 500 Hz, en rad/s.</p>","unit":"rad/s","answer":{"value":3141.592653589793,"rel":0.02},"display":"3 142 rad/s","explanation":"<p>ω = 2πf = 3 142 rad/s.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('placement-mobiles:si-val','placement-mobiles','Lecture d’un signal','numeric','[{"prompt":"<p>Pour x(t) = 2 sin(2π · 100 · t), calculez x à t = 1,25 ms, en volts.</p>","unit":"V","answer":{"value":1.414213562373095,"abs":0.03},"display":"1,414 V","explanation":"<p>x = 2 · sin(2π · 100 · 0,00125) = 1,414 V.</p>"},{"prompt":"<p>Pour x(t) = 4 sin(2π · 50 · t), calculez x à t = 2,5 ms, en volts.</p>","unit":"V","answer":{"value":2.82842712474619,"abs":0.03},"display":"2,828 V","explanation":"<p>x = 4 · sin(2π · 50 · 0,0025) = 2,828 V.</p>"},{"prompt":"<p>Pour x(t) = 3 sin(2π · 200 · t), calculez x à t = 0,5 ms, en volts.</p>","unit":"V","answer":{"value":1.7633557568774194,"abs":0.03},"display":"1,763 V","explanation":"<p>x = 3 · sin(2π · 200 · 0,0005) = 1,763 V.</p>"},{"prompt":"<p>Pour x(t) = 5 sin(2π · 125 · t), calculez x à t = 1 ms, en volts.</p>","unit":"V","answer":{"value":3.5355339059327373,"abs":0.03},"display":"3,536 V","explanation":"<p>x = 5 · sin(2π · 125 · 0,001) = 3,536 V.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('placement-mobiles:em-lam','placement-mobiles','Longueur d’onde','numeric','[{"prompt":"<p>Calculez la longueur d’onde dans le vide d’une onde de 100 MHz, <strong>en cm</strong>.</p>","unit":"cm","answer":{"value":299.792458,"rel":0.02},"display":"299,8 cm","explanation":"<p>λ = c/f = 299,8 cm.</p>"},{"prompt":"<p>Calculez la longueur d’onde dans le vide d’une onde de 900 MHz, <strong>en cm</strong>.</p>","unit":"cm","answer":{"value":33.31027311111111,"rel":0.02},"display":"33,31 cm","explanation":"<p>λ = c/f = 33,31 cm.</p>"},{"prompt":"<p>Calculez la longueur d’onde dans le vide d’une onde de 2 400 MHz, <strong>en cm</strong>.</p>","unit":"cm","answer":{"value":12.491352416666667,"rel":0.02},"display":"12,49 cm","explanation":"<p>λ = c/f = 12,49 cm.</p>"},{"prompt":"<p>Calculez la longueur d’onde dans le vide d’une onde de 5 000 MHz, <strong>en cm</strong>.</p>","unit":"cm","answer":{"value":5.99584916,"rel":0.02},"display":"5,996 cm","explanation":"<p>λ = c/f = 5,996 cm.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('placement-mobiles:em-coax','placement-mobiles','Vitesse dans un milieu','numeric','[{"prompt":"<p>Dans un câble de facteur de vitesse 0,66, calculez la longueur d’onde à 100 MHz, en mètres.</p>","unit":"m","answer":{"value":1.9786302228000001,"rel":0.02},"display":"1,979 m","explanation":"<p>λ = VF·c/f = 1,979 m.</p>"},{"prompt":"<p>Dans un câble de facteur de vitesse 0,66, calculez la longueur d’onde à 145 MHz, en mètres.</p>","unit":"m","answer":{"value":1.3645725674482758,"rel":0.02},"display":"1,365 m","explanation":"<p>λ = VF·c/f = 1,365 m.</p>"},{"prompt":"<p>Dans un câble de facteur de vitesse 0,85, calculez la longueur d’onde à 433 MHz, en mètres.</p>","unit":"m","answer":{"value":0.5885071346420323,"rel":0.02},"display":"0,5885 m","explanation":"<p>λ = VF·c/f = 0,5885 m.</p>"},{"prompt":"<p>Dans un câble de facteur de vitesse 0,85, calculez la longueur d’onde à 1 000 MHz, en mètres.</p>","unit":"m","answer":{"value":0.2548235893,"rel":0.02},"display":"0,2548 m","explanation":"<p>λ = VF·c/f = 0,2548 m.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('placement-mobiles:em-freq','placement-mobiles','Longueur d’onde','numeric','[{"prompt":"<p>Une onde a une longueur d’onde de 3 m dans le vide. Calculez sa fréquence, <strong>en MHz</strong>.</p>","unit":"MHz","answer":{"value":99.93081933333333,"rel":0.02},"display":"99,93 MHz","explanation":"<p>f = c/λ = 99,93 MHz.</p>"},{"prompt":"<p>Une onde a une longueur d’onde de 0,33 m dans le vide. Calculez sa fréquence, <strong>en MHz</strong>.</p>","unit":"MHz","answer":{"value":908.4619939393939,"rel":0.02},"display":"908,5 MHz","explanation":"<p>f = c/λ = 908,5 MHz.</p>"},{"prompt":"<p>Une onde a une longueur d’onde de 0,125 m dans le vide. Calculez sa fréquence, <strong>en MHz</strong>.</p>","unit":"MHz","answer":{"value":2398.339664,"rel":0.02},"display":"2 398 MHz","explanation":"<p>f = c/λ = 2 398 MHz.</p>"},{"prompt":"<p>Une onde a une longueur d’onde de 0,06 m dans le vide. Calculez sa fréquence, <strong>en MHz</strong>.</p>","unit":"MHz","answer":{"value":4996.540966666667,"rel":0.02},"display":"4 997 MHz","explanation":"<p>f = c/λ = 4 997 MHz.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('placement-mobiles:em-time','placement-mobiles','Vitesse dans un milieu','numeric','[{"prompt":"<p>Combien de temps une onde met-elle pour parcourir 3 000 m dans le vide ? Réponse <strong>en µs</strong>.</p>","unit":"µs","answer":{"value":10.00692285594456,"rel":0.02},"display":"10,01 µs","explanation":"<p>t = d/c = 10,01 µs.</p>"},{"prompt":"<p>Combien de temps une onde met-elle pour parcourir 36 000 m dans le vide ? Réponse <strong>en µs</strong>.</p>","unit":"µs","answer":{"value":120.08307427133474,"rel":0.02},"display":"120,1 µs","explanation":"<p>t = d/c = 120,1 µs.</p>"},{"prompt":"<p>Combien de temps une onde met-elle pour parcourir 150 m dans le vide ? Réponse <strong>en µs</strong>.</p>","unit":"µs","answer":{"value":0.500346142797228,"rel":0.02},"display":"0,5003 µs","explanation":"<p>t = d/c = 0,5003 µs.</p>"},{"prompt":"<p>Combien de temps une onde met-elle pour parcourir 1 200 m dans le vide ? Réponse <strong>en µs</strong>.</p>","unit":"µs","answer":{"value":4.002769142377824,"rel":0.02},"display":"4,003 µs","explanation":"<p>t = d/c = 4,003 µs.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('placement-mobiles:pr-fspl','placement-mobiles','Espace libre','numeric','[{"prompt":"<p>Calculez la perte en espace libre sur 1 km à 900 MHz, en dB.</p>","unit":"dB","answer":{"value":91.53263341066986,"abs":0.5},"display":"91,53 dB","explanation":"<p>FSPL = 20 log₁₀(4πdf/c) = 91,53 dB.</p>"},{"prompt":"<p>Calculez la perte en espace libre sur 5 km à 2 400 MHz, en dB.</p>","unit":"dB","answer":{"value":114.03140814283586,"abs":0.5},"display":"114 dB","explanation":"<p>FSPL = 20 log₁₀(4πdf/c) = 114 dB.</p>"},{"prompt":"<p>Calculez la perte en espace libre sur 10 km à 100 MHz, en dB.</p>","unit":"dB","answer":{"value":92.44778322188337,"abs":0.5},"display":"92,45 dB","explanation":"<p>FSPL = 20 log₁₀(4πdf/c) = 92,45 dB.</p>"},{"prompt":"<p>Calculez la perte en espace libre sur 0,2 km à 5 000 MHz, en dB.</p>","unit":"dB","answer":{"value":92.44778322188337,"abs":0.5},"display":"92,45 dB","explanation":"<p>FSPL = 20 log₁₀(4πdf/c) = 92,45 dB.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('placement-mobiles:pr-budget','placement-mobiles','Bilan de liaison','numeric','[{"prompt":"<p>Puissance émise 30 dBm, gains d’antennes 10 dBi et 2 dBi, perte de trajet 110 dB. Calculez la puissance reçue, en dBm.</p>","unit":"dBm","answer":{"value":-68,"abs":0.1},"display":"−68 dBm","explanation":"<p>Pr = Pe + Ge + Gr − L = −68 dBm.</p>"},{"prompt":"<p>Puissance émise 20 dBm, gains d’antennes 6 dBi et 6 dBi, perte de trajet 95 dB. Calculez la puissance reçue, en dBm.</p>","unit":"dBm","answer":{"value":-63,"abs":0.1},"display":"−63 dBm","explanation":"<p>Pr = Pe + Ge + Gr − L = −63 dBm.</p>"},{"prompt":"<p>Puissance émise 43 dBm, gains d’antennes 15 dBi et 0 dBi, perte de trajet 130 dB. Calculez la puissance reçue, en dBm.</p>","unit":"dBm","answer":{"value":-72,"abs":0.1},"display":"−72 dBm","explanation":"<p>Pr = Pe + Ge + Gr − L = −72 dBm.</p>"},{"prompt":"<p>Puissance émise 10 dBm, gains d’antennes 3 dBi et 3 dBi, perte de trajet 80 dB. Calculez la puissance reçue, en dBm.</p>","unit":"dBm","answer":{"value":-64,"abs":0.1},"display":"−64 dBm","explanation":"<p>Pr = Pe + Ge + Gr − L = −64 dBm.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('placement-mobiles:pr-horizon','placement-mobiles','Horizon radio','numeric','[{"prompt":"<p>Avec des antennes à 30 m et 1,5 m (modèle 4/3 de la Terre), calculez l’horizon radio, <strong>en km</strong>.</p>","unit":"km","answer":{"value":27.612118239346188,"rel":0.03},"display":"27,61 km","explanation":"<p>d ≈ 4,12(√h₁ + √h₂) = 27,61 km.</p>"},{"prompt":"<p>Avec des antennes à 50 m et 10 m (modèle 4/3 de la Terre), calculez l’horizon radio, <strong>en km</strong>.</p>","unit":"km","answer":{"value":42.16138334477948,"rel":0.03},"display":"42,16 km","explanation":"<p>d ≈ 4,12(√h₁ + √h₂) = 42,16 km.</p>"},{"prompt":"<p>Avec des antennes à 100 m et 2 m (modèle 4/3 de la Terre), calculez l’horizon radio, <strong>en km</strong>.</p>","unit":"km","answer":{"value":47.02655987697715,"rel":0.03},"display":"47,03 km","explanation":"<p>d ≈ 4,12(√h₁ + √h₂) = 47,03 km.</p>"},{"prompt":"<p>Avec des antennes à 20 m et 20 m (modèle 4/3 de la Terre), calculez l’horizon radio, <strong>en km</strong>.</p>","unit":"km","answer":{"value":36.850400269196534,"rel":0.03},"display":"36,85 km","explanation":"<p>d ≈ 4,12(√h₁ + √h₂) = 36,85 km.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('placement-mobiles:pr-fresnel','placement-mobiles','Zone de Fresnel','numeric','[{"prompt":"<p>À 900 MHz, un obstacle se trouve à 1 000 m de l’émetteur et 1 000 m du récepteur. Calculez le rayon de la première zone de Fresnel, en mètres.</p>","unit":"m","answer":{"value":12.90547812192774,"rel":0.03},"display":"12,91 m","explanation":"<p>r = √(λ·d₁·d₂/(d₁+d₂)) = 12,91 m.</p>"},{"prompt":"<p>À 2 400 MHz, un obstacle se trouve à 500 m de l’émetteur et 1 500 m du récepteur. Calculez le rayon de la première zone de Fresnel, en mètres.</p>","unit":"m","answer":{"value":6.844163320852301,"rel":0.03},"display":"6,844 m","explanation":"<p>r = √(λ·d₁·d₂/(d₁+d₂)) = 6,844 m.</p>"},{"prompt":"<p>À 5 000 MHz, un obstacle se trouve à 2 000 m de l’émetteur et 2 000 m du récepteur. Calculez le rayon de la première zone de Fresnel, en mètres.</p>","unit":"m","answer":{"value":7.743286873156644,"rel":0.03},"display":"7,743 m","explanation":"<p>r = √(λ·d₁·d₂/(d₁+d₂)) = 7,743 m.</p>"},{"prompt":"<p>À 100 MHz, un obstacle se trouve à 5 000 m de l’émetteur et 5 000 m du récepteur. Calculez le rayon de la première zone de Fresnel, en mètres.</p>","unit":"m","answer":{"value":86.57257908830023,"rel":0.03},"display":"86,57 m","explanation":"<p>r = √(λ·d₁·d₂/(d₁+d₂)) = 86,57 m.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('placement-mobiles:mo-ambw','placement-mobiles','Modulation AM','numeric','[{"prompt":"<p>Un signal modulant de 3 kHz module une porteuse en AM. Calculez la largeur de bande, <strong>en kHz</strong>.</p>","unit":"kHz","answer":{"value":6,"rel":0.02},"display":"6 kHz","explanation":"<p>B = 2fm = 6 kHz.</p>"},{"prompt":"<p>Un signal modulant de 4,5 kHz module une porteuse en AM. Calculez la largeur de bande, <strong>en kHz</strong>.</p>","unit":"kHz","answer":{"value":9,"rel":0.02},"display":"9 kHz","explanation":"<p>B = 2fm = 9 kHz.</p>"},{"prompt":"<p>Un signal modulant de 5 kHz module une porteuse en AM. Calculez la largeur de bande, <strong>en kHz</strong>.</p>","unit":"kHz","answer":{"value":10,"rel":0.02},"display":"10 kHz","explanation":"<p>B = 2fm = 10 kHz.</p>"},{"prompt":"<p>Un signal modulant de 10 kHz module une porteuse en AM. Calculez la largeur de bande, <strong>en kHz</strong>.</p>","unit":"kHz","answer":{"value":20,"rel":0.02},"display":"20 kHz","explanation":"<p>B = 2fm = 20 kHz.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('placement-mobiles:mo-eff','placement-mobiles','Modulation AM','numeric','[{"prompt":"<p>Calculez le rendement en puissance d’une AM d’indice m = 0,3, <strong>en %</strong>.</p>","unit":"%","answer":{"value":4.30622009569378,"abs":0.5},"display":"4,306 %","explanation":"<p>η = m²/(2+m²) = 4,306 %.</p>"},{"prompt":"<p>Calculez le rendement en puissance d’une AM d’indice m = 0,5, <strong>en %</strong>.</p>","unit":"%","answer":{"value":11.11111111111111,"abs":0.5},"display":"11,11 %","explanation":"<p>η = m²/(2+m²) = 11,11 %.</p>"},{"prompt":"<p>Calculez le rendement en puissance d’une AM d’indice m = 0,8, <strong>en %</strong>.</p>","unit":"%","answer":{"value":24.242424242424246,"abs":0.5},"display":"24,24 %","explanation":"<p>η = m²/(2+m²) = 24,24 %.</p>"},{"prompt":"<p>Calculez le rendement en puissance d’une AM d’indice m = 1, <strong>en %</strong>.</p>","unit":"%","answer":{"value":33.33333333333333,"abs":0.5},"display":"33,33 %","explanation":"<p>η = m²/(2+m²) = 33,33 %.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('placement-mobiles:mo-carson','placement-mobiles','Modulation FM','numeric','[{"prompt":"<p>En FM, l’excursion est de 75 kHz et la fréquence modulante de 15 kHz. Calculez la largeur de bande de Carson, <strong>en kHz</strong>.</p>","unit":"kHz","answer":{"value":180,"rel":0.02},"display":"180 kHz","explanation":"<p>B ≈ 2(Δf + fm) = 180 kHz.</p>"},{"prompt":"<p>En FM, l’excursion est de 5 kHz et la fréquence modulante de 3 kHz. Calculez la largeur de bande de Carson, <strong>en kHz</strong>.</p>","unit":"kHz","answer":{"value":16,"rel":0.02},"display":"16 kHz","explanation":"<p>B ≈ 2(Δf + fm) = 16 kHz.</p>"},{"prompt":"<p>En FM, l’excursion est de 25 kHz et la fréquence modulante de 5 kHz. Calculez la largeur de bande de Carson, <strong>en kHz</strong>.</p>","unit":"kHz","answer":{"value":60,"rel":0.02},"display":"60 kHz","explanation":"<p>B ≈ 2(Δf + fm) = 60 kHz.</p>"},{"prompt":"<p>En FM, l’excursion est de 50 kHz et la fréquence modulante de 10 kHz. Calculez la largeur de bande de Carson, <strong>en kHz</strong>.</p>","unit":"kHz","answer":{"value":120,"rel":0.02},"display":"120 kHz","explanation":"<p>B ≈ 2(Δf + fm) = 120 kHz.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('placement-mobiles:mo-beta','placement-mobiles','Modulation FM','numeric','[{"prompt":"<p>Calculez l’indice de modulation β pour Δf = 75 kHz et fm = 15 kHz.</p>","unit":"","answer":{"value":5,"rel":0.02},"display":"5","explanation":"<p>β = Δf/fm = 5.</p>"},{"prompt":"<p>Calculez l’indice de modulation β pour Δf = 5 kHz et fm = 2,5 kHz.</p>","unit":"","answer":{"value":2,"rel":0.02},"display":"2","explanation":"<p>β = Δf/fm = 2.</p>"},{"prompt":"<p>Calculez l’indice de modulation β pour Δf = 30 kHz et fm = 10 kHz.</p>","unit":"","answer":{"value":3,"rel":0.02},"display":"3","explanation":"<p>β = Δf/fm = 3.</p>"},{"prompt":"<p>Calculez l’indice de modulation β pour Δf = 50 kHz et fm = 5 kHz.</p>","unit":"","answer":{"value":10,"rel":0.02},"display":"10","explanation":"<p>β = Δf/fm = 10.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('placement-mobiles:mb-n','placement-mobiles','Motifs de réutilisation','numeric','[{"prompt":"<p>Calculez la taille du motif N pour i = 1 et j = 1.</p>","unit":"","answer":{"value":3,"abs":0.01},"display":"3","explanation":"<p>N = i² + ij + j² = 3.</p>"},{"prompt":"<p>Calculez la taille du motif N pour i = 2 et j = 0.</p>","unit":"","answer":{"value":4,"abs":0.01},"display":"4","explanation":"<p>N = i² + ij + j² = 4.</p>"},{"prompt":"<p>Calculez la taille du motif N pour i = 2 et j = 1.</p>","unit":"","answer":{"value":7,"abs":0.01},"display":"7","explanation":"<p>N = i² + ij + j² = 7.</p>"},{"prompt":"<p>Calculez la taille du motif N pour i = 2 et j = 2.</p>","unit":"","answer":{"value":12,"abs":0.01},"display":"12","explanation":"<p>N = i² + ij + j² = 12.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('placement-mobiles:mb-d','placement-mobiles','Réutilisation des fréquences','numeric','[{"prompt":"<p>Cellules de rayon 1 km, motif N = 7. Calculez la distance de réutilisation, en km.</p>","unit":"km","answer":{"value":4.58257569495584,"rel":0.02},"display":"4,583 km","explanation":"<p>D = R√(3N) = 4,583 km.</p>"},{"prompt":"<p>Cellules de rayon 2 km, motif N = 4. Calculez la distance de réutilisation, en km.</p>","unit":"km","answer":{"value":6.928203230275509,"rel":0.02},"display":"6,928 km","explanation":"<p>D = R√(3N) = 6,928 km.</p>"},{"prompt":"<p>Cellules de rayon 0,5 km, motif N = 3. Calculez la distance de réutilisation, en km.</p>","unit":"km","answer":{"value":1.5,"rel":0.02},"display":"1,5 km","explanation":"<p>D = R√(3N) = 1,5 km.</p>"},{"prompt":"<p>Cellules de rayon 3 km, motif N = 12. Calculez la distance de réutilisation, en km.</p>","unit":"km","answer":{"value":18,"rel":0.02},"display":"18 km","explanation":"<p>D = R√(3N) = 18 km.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('placement-mobiles:mb-ch','placement-mobiles','Capacité','numeric','[{"prompt":"<p>Un opérateur dispose de 420 canaux, motif N = 7. Combien de canaux par cellule ?</p>","unit":"","answer":{"value":60,"abs":0.01},"display":"60","explanation":"<p>S/N = 60 canaux.</p>"},{"prompt":"<p>Un opérateur dispose de 120 canaux, motif N = 4. Combien de canaux par cellule ?</p>","unit":"","answer":{"value":30,"abs":0.01},"display":"30","explanation":"<p>S/N = 30 canaux.</p>"},{"prompt":"<p>Un opérateur dispose de 300 canaux, motif N = 3. Combien de canaux par cellule ?</p>","unit":"","answer":{"value":100,"abs":0.01},"display":"100","explanation":"<p>S/N = 100 canaux.</p>"},{"prompt":"<p>Un opérateur dispose de 840 canaux, motif N = 12. Combien de canaux par cellule ?</p>","unit":"","answer":{"value":70,"abs":0.01},"display":"70","explanation":"<p>S/N = 70 canaux.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('placement-mobiles:mb-ci','placement-mobiles','Interférences','numeric','[{"prompt":"<p>Avec le modèle à 6 interféreurs, motif N = 7 et exposant d’affaiblissement n = 4, calculez C/I, en dB.</p>","unit":"dB","answer":{"value":18.66287339084195,"abs":0.3},"display":"18,66 dB","explanation":"<p>C/I = (√(3N))ⁿ/6 = 18,66 dB.</p>"},{"prompt":"<p>Avec le modèle à 6 interféreurs, motif N = 3 et exposant d’affaiblissement n = 4, calculez C/I, en dB.</p>","unit":"dB","answer":{"value":11.303337684950062,"abs":0.3},"display":"11,3 dB","explanation":"<p>C/I = (√(3N))ⁿ/6 = 11,3 dB.</p>"},{"prompt":"<p>Avec le modèle à 6 interféreurs, motif N = 4 et exposant d’affaiblissement n = 3,5, calculez C/I, en dB.</p>","unit":"dB","answer":{"value":11.104159301996997,"abs":0.3},"display":"11,1 dB","explanation":"<p>C/I = (√(3N))ⁿ/6 = 11,1 dB.</p>"},{"prompt":"<p>Avec le modèle à 6 interféreurs, motif N = 12 et exposant d’affaiblissement n = 4, calculez C/I, en dB.</p>","unit":"dB","answer":{"value":23.34453751150931,"abs":0.3},"display":"23,34 dB","explanation":"<p>C/I = (√(3N))ⁿ/6 = 23,34 dB.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into public.assessments (id,title,description,kind,competency,question_count,pass_percent,duration_seconds,max_attempts,cooldown_minutes,prerequisites,grants,status) values ('placement-electronique','Positionnement : électronique','Circuits, courant alternatif et diodes.','placement',null,10,80,1500,2,1440,array[]::text[],array['circuits','ac','diodes']::text[],'published') on conflict (id) do update set title=excluded.title, description=excluded.description, prerequisites=excluded.prerequisites, grants=excluded.grants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('placement-electronique:ci-ohm','placement-electronique','Loi d’Ohm','numeric','[{"prompt":"<p>Une résistance de 470 Ω est alimentée sous 12 V. Calculez le courant, <strong>en mA</strong>.</p>","unit":"mA","answer":{"value":25.53191489361702,"rel":0.02},"display":"25,53 mA","explanation":"<p>I = U/R = 12 / 470 = 25,53 mA.</p>"},{"prompt":"<p>Une résistance de 220 Ω est alimentée sous 5 V. Calculez le courant, <strong>en mA</strong>.</p>","unit":"mA","answer":{"value":22.727272727272727,"rel":0.02},"display":"22,73 mA","explanation":"<p>I = U/R = 5 / 220 = 22,73 mA.</p>"},{"prompt":"<p>Une résistance de 1 000 Ω est alimentée sous 9 V. Calculez le courant, <strong>en mA</strong>.</p>","unit":"mA","answer":{"value":9,"rel":0.02},"display":"9 mA","explanation":"<p>I = U/R = 9 / 1 000 = 9 mA.</p>"},{"prompt":"<p>Une résistance de 680 Ω est alimentée sous 24 V. Calculez le courant, <strong>en mA</strong>.</p>","unit":"mA","answer":{"value":35.294117647058826,"rel":0.02},"display":"35,29 mA","explanation":"<p>I = U/R = 24 / 680 = 35,29 mA.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('placement-electronique:ci-par','placement-electronique','Association de résistances','numeric','[{"prompt":"<p>Deux résistances de 100 Ω et 100 Ω sont en parallèle. Calculez la résistance équivalente, en Ω.</p>","unit":"Ω","answer":{"value":50,"rel":0.02},"display":"50 Ω","explanation":"<p>Req = R₁R₂/(R₁+R₂) = 50 Ω.</p>"},{"prompt":"<p>Deux résistances de 220 Ω et 330 Ω sont en parallèle. Calculez la résistance équivalente, en Ω.</p>","unit":"Ω","answer":{"value":132,"rel":0.02},"display":"132 Ω","explanation":"<p>Req = R₁R₂/(R₁+R₂) = 132 Ω.</p>"},{"prompt":"<p>Deux résistances de 1 000 Ω et 470 Ω sont en parallèle. Calculez la résistance équivalente, en Ω.</p>","unit":"Ω","answer":{"value":319.7278911564626,"rel":0.02},"display":"319,7 Ω","explanation":"<p>Req = R₁R₂/(R₁+R₂) = 319,7 Ω.</p>"},{"prompt":"<p>Deux résistances de 150 Ω et 680 Ω sont en parallèle. Calculez la résistance équivalente, en Ω.</p>","unit":"Ω","answer":{"value":122.89156626506025,"rel":0.02},"display":"122,9 Ω","explanation":"<p>Req = R₁R₂/(R₁+R₂) = 122,9 Ω.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('placement-electronique:ci-div','placement-electronique','Diviseur de tension','numeric','[{"prompt":"<p>Un diviseur à vide est alimenté sous 12 V, avec R₁ = 1 000 Ω côté source et R₂ = 2 200 Ω côté masse. Calculez la tension aux bornes de R₂, en V.</p>","unit":"V","answer":{"value":8.25,"rel":0.02},"display":"8,25 V","explanation":"<p>U₂ = E·R₂/(R₁+R₂) = 8,25 V.</p>"},{"prompt":"<p>Un diviseur à vide est alimenté sous 9 V, avec R₁ = 470 Ω côté source et R₂ = 470 Ω côté masse. Calculez la tension aux bornes de R₂, en V.</p>","unit":"V","answer":{"value":4.5,"rel":0.02},"display":"4,5 V","explanation":"<p>U₂ = E·R₂/(R₁+R₂) = 4,5 V.</p>"},{"prompt":"<p>Un diviseur à vide est alimenté sous 5 V, avec R₁ = 3 300 Ω côté source et R₂ = 1 000 Ω côté masse. Calculez la tension aux bornes de R₂, en V.</p>","unit":"V","answer":{"value":1.1627906976744187,"rel":0.02},"display":"1,163 V","explanation":"<p>U₂ = E·R₂/(R₁+R₂) = 1,163 V.</p>"},{"prompt":"<p>Un diviseur à vide est alimenté sous 24 V, avec R₁ = 10 000 Ω côté source et R₂ = 4 700 Ω côté masse. Calculez la tension aux bornes de R₂, en V.</p>","unit":"V","answer":{"value":7.673469387755102,"rel":0.02},"display":"7,673 V","explanation":"<p>U₂ = E·R₂/(R₁+R₂) = 7,673 V.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('placement-electronique:ci-pow','placement-electronique','Puissance','numeric','[{"prompt":"<p>Une résistance de 100 Ω est parcourue par 50 mA. Calculez la puissance dissipée, <strong>en mW</strong>.</p>","unit":"mW","answer":{"value":250,"rel":0.02},"display":"250 mW","explanation":"<p>P = R·I² = 250 mW.</p>"},{"prompt":"<p>Une résistance de 470 Ω est parcourue par 20 mA. Calculez la puissance dissipée, <strong>en mW</strong>.</p>","unit":"mW","answer":{"value":188,"rel":0.02},"display":"188 mW","explanation":"<p>P = R·I² = 188 mW.</p>"},{"prompt":"<p>Une résistance de 220 Ω est parcourue par 100 mA. Calculez la puissance dissipée, <strong>en mW</strong>.</p>","unit":"mW","answer":{"value":2200,"rel":0.02},"display":"2 200 mW","explanation":"<p>P = R·I² = 2 200 mW.</p>"},{"prompt":"<p>Une résistance de 1 000 Ω est parcourue par 10 mA. Calculez la puissance dissipée, <strong>en mW</strong>.</p>","unit":"mW","answer":{"value":100,"rel":0.02},"display":"100 mW","explanation":"<p>P = R·I² = 100 mW.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('placement-electronique:ac-eff','placement-electronique','Valeur efficace','numeric','[{"prompt":"<p>Une sinusoïde a une valeur efficace de 230 V. Calculez son amplitude, en V.</p>","unit":"V","answer":{"value":325.2691193458119,"rel":0.02},"display":"325,3 V","explanation":"<p>V<sub>p</sub> = V<sub>eff</sub> × √2.</p>"},{"prompt":"<p>Une sinusoïde a une valeur efficace de 120 V. Calculez son amplitude, en V.</p>","unit":"V","answer":{"value":169.7056274847714,"rel":0.02},"display":"169,7 V","explanation":"<p>V<sub>p</sub> = V<sub>eff</sub> × √2.</p>"},{"prompt":"<p>Une sinusoïde a une valeur efficace de 12 V. Calculez son amplitude, en V.</p>","unit":"V","answer":{"value":16.970562748477143,"rel":0.02},"display":"16,97 V","explanation":"<p>V<sub>p</sub> = V<sub>eff</sub> × √2.</p>"},{"prompt":"<p>Une sinusoïde a une valeur efficace de 48 V. Calculez son amplitude, en V.</p>","unit":"V","answer":{"value":67.88225099390857,"rel":0.02},"display":"67,88 V","explanation":"<p>V<sub>p</sub> = V<sub>eff</sub> × √2.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('placement-electronique:ac-xc','placement-electronique','Réactances','numeric','[{"prompt":"<p>Calculez la réactance d’un condensateur de 10 µF à 50 Hz, en Ω.</p>","unit":"Ω","answer":{"value":318.30988618379064,"rel":0.02},"display":"318,3 Ω","explanation":"<p>X<sub>C</sub> = 1/(2πfC).</p>"},{"prompt":"<p>Calculez la réactance d’un condensateur de 1 µF à 1 000 Hz, en Ω.</p>","unit":"Ω","answer":{"value":159.15494309189535,"rel":0.02},"display":"159,2 Ω","explanation":"<p>X<sub>C</sub> = 1/(2πfC).</p>"},{"prompt":"<p>Calculez la réactance d’un condensateur de 100 µF à 60 Hz, en Ω.</p>","unit":"Ω","answer":{"value":26.525823848649225,"rel":0.02},"display":"26,53 Ω","explanation":"<p>X<sub>C</sub> = 1/(2πfC).</p>"},{"prompt":"<p>Calculez la réactance d’un condensateur de 0,1 µF à 10 000 Hz, en Ω.</p>","unit":"Ω","answer":{"value":159.15494309189532,"rel":0.02},"display":"159,2 Ω","explanation":"<p>X<sub>C</sub> = 1/(2πfC).</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('placement-electronique:ac-z','placement-electronique','Impédance','numeric','[{"prompt":"<p>RLC série : R = 100 Ω, L = 0,1 H, C = 10 µF, f = 200 Hz. Calculez |Z|, en Ω.</p>","unit":"Ω","answer":{"value":110.10876903947788,"rel":0.02},"display":"110,1 Ω","explanation":"<p>|Z| = √(R² + (X<sub>L</sub> − X<sub>C</sub>)²).</p>"},{"prompt":"<p>RLC série : R = 50 Ω, L = 0,2 H, C = 20 µF, f = 100 Hz. Calculez |Z|, en Ω.</p>","unit":"Ω","answer":{"value":67.99956631765444,"rel":0.02},"display":"68 Ω","explanation":"<p>|Z| = √(R² + (X<sub>L</sub> − X<sub>C</sub>)²).</p>"},{"prompt":"<p>RLC série : R = 220 Ω, L = 0,05 H, C = 1 µF, f = 1 000 Hz. Calculez |Z|, en Ω.</p>","unit":"Ω","answer":{"value":269.1214222641483,"rel":0.02},"display":"269,1 Ω","explanation":"<p>|Z| = √(R² + (X<sub>L</sub> − X<sub>C</sub>)²).</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('placement-electronique:ac-res','placement-electronique','Résonance','numeric','[{"prompt":"<p>Calculez la fréquence de résonance pour L = 1 mH et C = 100 nF, en kHz.</p>","unit":"kHz","answer":{"value":15.915494309189533,"rel":0.02},"display":"15,92 kHz","explanation":"<p>f₀ = 1/(2π√(LC)).</p>"},{"prompt":"<p>Calculez la fréquence de résonance pour L = 10 mH et C = 1 nF, en kHz.</p>","unit":"kHz","answer":{"value":50.329212104487034,"rel":0.02},"display":"50,33 kHz","explanation":"<p>f₀ = 1/(2π√(LC)).</p>"},{"prompt":"<p>Calculez la fréquence de résonance pour L = 100 mH et C = 10 nF, en kHz.</p>","unit":"kHz","answer":{"value":5.032921210448703,"rel":0.02},"display":"5,033 kHz","explanation":"<p>f₀ = 1/(2π√(LC)).</p>"},{"prompt":"<p>Calculez la fréquence de résonance pour L = 0,5 mH et C = 47 nF, en kHz.</p>","unit":"kHz","answer":{"value":32.831157950418,"rel":0.02},"display":"32,83 kHz","explanation":"<p>f₀ = 1/(2π√(LC)).</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('placement-electronique:di-crete','placement-electronique','Redressement','numeric','[{"prompt":"<p>Un secondaire délivre 9 V efficaces. Calculez la tension de crête, en V.</p>","unit":"V","answer":{"value":12.727922061357857,"rel":0.02},"display":"12,73 V","explanation":"<p>V<sub>p</sub> = V<sub>eff</sub> × √2.</p>"},{"prompt":"<p>Un secondaire délivre 12 V efficaces. Calculez la tension de crête, en V.</p>","unit":"V","answer":{"value":16.970562748477143,"rel":0.02},"display":"16,97 V","explanation":"<p>V<sub>p</sub> = V<sub>eff</sub> × √2.</p>"},{"prompt":"<p>Un secondaire délivre 24 V efficaces. Calculez la tension de crête, en V.</p>","unit":"V","answer":{"value":33.941125496954285,"rel":0.02},"display":"33,94 V","explanation":"<p>V<sub>p</sub> = V<sub>eff</sub> × √2.</p>"},{"prompt":"<p>Un secondaire délivre 6 V efficaces. Calculez la tension de crête, en V.</p>","unit":"V","answer":{"value":8.485281374238571,"rel":0.02},"display":"8,485 V","explanation":"<p>V<sub>p</sub> = V<sub>eff</sub> × √2.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('placement-electronique:di-moy','placement-electronique','Redressement','numeric','[{"prompt":"<p>Redressement double alternance idéal, crête 10 V, sans condensateur. Calculez la tension moyenne, en V.</p>","unit":"V","answer":{"value":6.366197723675814,"rel":0.02},"display":"6,366 V","explanation":"<p>V<sub>moy</sub> = 2V<sub>p</sub>/π.</p>"},{"prompt":"<p>Redressement double alternance idéal, crête 17 V, sans condensateur. Calculez la tension moyenne, en V.</p>","unit":"V","answer":{"value":10.822536130248883,"rel":0.02},"display":"10,82 V","explanation":"<p>V<sub>moy</sub> = 2V<sub>p</sub>/π.</p>"},{"prompt":"<p>Redressement double alternance idéal, crête 34 V, sans condensateur. Calculez la tension moyenne, en V.</p>","unit":"V","answer":{"value":21.645072260497766,"rel":0.02},"display":"21,65 V","explanation":"<p>V<sub>moy</sub> = 2V<sub>p</sub>/π.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('placement-electronique:di-c','placement-electronique','Filtrage','numeric','[{"prompt":"<p>Pont à 50 Hz, 1 A de charge, 2 V d’ondulation admis. Calculez C minimal, en µF.</p>","unit":"µF","answer":{"value":5000,"rel":0.03},"display":"5 000 µF","explanation":"<p>C ≥ I/(2f·ΔV).</p>"},{"prompt":"<p>Pont à 50 Hz, 0,5 A de charge, 1 V d’ondulation admis. Calculez C minimal, en µF.</p>","unit":"µF","answer":{"value":5000,"rel":0.03},"display":"5 000 µF","explanation":"<p>C ≥ I/(2f·ΔV).</p>"},{"prompt":"<p>Pont à 50 Hz, 2 A de charge, 2,5 V d’ondulation admis. Calculez C minimal, en µF.</p>","unit":"µF","answer":{"value":8000,"rel":0.03},"display":"8 000 µF","explanation":"<p>C ≥ I/(2f·ΔV).</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('placement-electronique:di-z','placement-electronique','Stabilisation','numeric','[{"prompt":"<p>Entrée 12 V, R<sub>s</sub> = 100 Ω, V<sub>Z</sub> = 5,1 V, charge 470 Ω. Calculez I<sub>Z</sub>, en mA.</p>","unit":"mA","answer":{"value":58.14893617021277,"rel":0.03},"display":"58,15 mA","explanation":"<p>I<sub>Z</sub> = (V<sub>e</sub> − V<sub>Z</sub>)/R<sub>s</sub> − V<sub>Z</sub>/R<sub>L</sub>.</p>"},{"prompt":"<p>Entrée 15 V, R<sub>s</sub> = 220 Ω, V<sub>Z</sub> = 5,1 V, charge 1 000 Ω. Calculez I<sub>Z</sub>, en mA.</p>","unit":"mA","answer":{"value":39.9,"rel":0.03},"display":"39,9 mA","explanation":"<p>I<sub>Z</sub> = (V<sub>e</sub> − V<sub>Z</sub>)/R<sub>s</sub> − V<sub>Z</sub>/R<sub>L</sub>.</p>"},{"prompt":"<p>Entrée 9 V, R<sub>s</sub> = 68 Ω, V<sub>Z</sub> = 5,1 V, charge 330 Ω. Calculez I<sub>Z</sub>, en mA.</p>","unit":"mA","answer":{"value":41.898395721925134,"rel":0.03},"display":"41,9 mA","explanation":"<p>I<sub>Z</sub> = (V<sub>e</sub> − V<sub>Z</sub>)/R<sub>s</sub> − V<sub>Z</sub>/R<sub>L</sub>.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
