insert into private.questions (id,assessment_id,skill,kind,variants) values ('placement-iot:ii-act','placement-iot','Architecture','qcm','[{"prompt":"<p>Lequel est un actionneur ?</p>","options":[{"id":"a","label":"Une électrovanne"},{"id":"b","label":"Une thermistance"},{"id":"c","label":"Une photodiode"},{"id":"d","label":"Un microphone"}],"answer":{"id":"a"},"display":"Une électrovanne","explanation":"<p>Elle agit sur le monde physique.</p>"},{"prompt":"<p>Lequel est un actionneur ?</p>","options":[{"id":"a","label":"Une thermistance"},{"id":"b","label":"Une électrovanne"},{"id":"c","label":"Une photodiode"},{"id":"d","label":"Un microphone"}],"answer":{"id":"b"},"display":"Une électrovanne","explanation":"<p>Elle agit sur le monde physique.</p>"},{"prompt":"<p>Lequel est un actionneur ?</p>","options":[{"id":"a","label":"Une thermistance"},{"id":"b","label":"Une photodiode"},{"id":"c","label":"Une électrovanne"},{"id":"d","label":"Un microphone"}],"answer":{"id":"c"},"display":"Une électrovanne","explanation":"<p>Elle agit sur le monde physique.</p>"},{"prompt":"<p>Lequel est un actionneur ?</p>","options":[{"id":"a","label":"Une thermistance"},{"id":"b","label":"Une photodiode"},{"id":"c","label":"Un microphone"},{"id":"d","label":"Une électrovanne"}],"answer":{"id":"d"},"display":"Une électrovanne","explanation":"<p>Elle agit sur le monde physique.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('placement-iot:im-ts','placement-iot','LoRa','numeric','[{"prompt":"<p>SF10, 125 kHz. Calculez T<sub>s</sub>, en ms.</p>","unit":"ms","answer":{"value":8.192,"rel":0.01},"display":"8,192 ms","explanation":"<p>T<sub>s</sub> = 2<sup>SF</sup>/BW.</p>"},{"prompt":"<p>SF7, 125 kHz. Calculez T<sub>s</sub>, en ms.</p>","unit":"ms","answer":{"value":1.024,"rel":0.01},"display":"1,024 ms","explanation":"<p>T<sub>s</sub> = 2<sup>SF</sup>/BW.</p>"},{"prompt":"<p>SF12, 125 kHz. Calculez T<sub>s</sub>, en ms.</p>","unit":"ms","answer":{"value":32.768,"rel":0.01},"display":"32,77 ms","explanation":"<p>T<sub>s</sub> = 2<sup>SF</sup>/BW.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('placement-iot:im-toa','placement-iot','LoRa','numeric','[{"prompt":"<p>SF7, 125 kHz, CR 4/5, 20 octets, préambule 8, CRC activé, en-tête explicite. Calculez le temps d’antenne, en ms.</p>","unit":"ms","answer":{"value":56.57599999999999,"rel":0.03},"display":"56,58 ms","explanation":"<p>T = (n + 4,25)T<sub>s</sub> + n<sub>charge</sub>T<sub>s</sub>.</p>"},{"prompt":"<p>SF9, 125 kHz, CR 4/5, 20 octets, préambule 8, CRC activé, en-tête explicite. Calculez le temps d’antenne, en ms.</p>","unit":"ms","answer":{"value":185.344,"rel":0.03},"display":"185,3 ms","explanation":"<p>T = (n + 4,25)T<sub>s</sub> + n<sub>charge</sub>T<sub>s</sub>.</p>"},{"prompt":"<p>SF12, 125 kHz, CR 4/5, 12 octets, préambule 8, CRC activé, en-tête explicite. Calculez le temps d’antenne, en ms.</p>","unit":"ms","answer":{"value":1155.0720000000001,"rel":0.03},"display":"1 155 ms","explanation":"<p>T = (n + 4,25)T<sub>s</sub> + n<sub>charge</sub>T<sub>s</sub>.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('placement-iot:im-s','placement-iot','Portée','numeric','[{"prompt":"<p>SF7, 125 kHz, NF = 6 dB. La limite de SNR est −7,5 dB. Calculez la sensibilité, en dBm.</p>","unit":"dBm","answer":{"value":-124.53089986991944,"abs":0.3},"display":"−124,5 dBm","explanation":"<p>S = −174 + 10 log₁₀ BW + NF + SNR.</p>"},{"prompt":"<p>SF10, 125 kHz, NF = 6 dB. La limite de SNR est −15 dB. Calculez la sensibilité, en dBm.</p>","unit":"dBm","answer":{"value":-132.03089986991944,"abs":0.3},"display":"−132 dBm","explanation":"<p>S = −174 + 10 log₁₀ BW + NF + SNR.</p>"},{"prompt":"<p>SF12, 125 kHz, NF = 6 dB. La limite de SNR est −20 dB. Calculez la sensibilité, en dBm.</p>","unit":"dBm","answer":{"value":-137.03089986991944,"abs":0.3},"display":"−137 dBm","explanation":"<p>S = −174 + 10 log₁₀ BW + NF + SNR.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
insert into private.questions (id,assessment_id,skill,kind,variants) values ('placement-iot:im-dc','placement-iot','Réglementation','numeric','[{"prompt":"<p>Paquet de 0,5 s, cycle autorisé 1 %. Calculez la période minimale, en s.</p>","unit":"s","answer":{"value":50,"rel":0.02},"display":"50 s","explanation":"<p>T<sub>min</sub> = T/D.</p>"},{"prompt":"<p>Paquet de 1,3 s, cycle autorisé 1 %. Calculez la période minimale, en s.</p>","unit":"s","answer":{"value":130,"rel":0.02},"display":"130 s","explanation":"<p>T<sub>min</sub> = T/D.</p>"},{"prompt":"<p>Paquet de 0,1 s, cycle autorisé 0,1 %. Calculez la période minimale, en s.</p>","unit":"s","answer":{"value":100,"rel":0.02},"display":"100 s","explanation":"<p>T<sub>min</sub> = T/D.</p>"}]'::jsonb) on conflict (id) do update set skill=excluded.skill, kind=excluded.kind, variants=excluded.variants;
